-- Session-33 security closure: RPC tenant guards (GENERATED by scripts/gen_rpc_tenant_guards.py)
-- SECURITY DEFINER functions with a business_id param are explicitly gated to members
-- (empty result for non-members). REVOKE-only classes (Brain-poisoning vectors, cron
-- fan-outs, admin helpers) are revoked from public roles — service role unaffected.

CREATE OR REPLACE FUNCTION public.blocked_work(p_business_id UUID)
RETURNS TABLE(dependent_type TEXT, dependent_id UUID, unsatisfied_count BIGINT)
AS $guard$

BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT dependent_type, dependent_id, count(*) AS unsatisfied_count
  FROM work_dependencies
  WHERE business_id = p_business_id AND satisfied = FALSE
  GROUP BY dependent_type, dependent_id;
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.broadcast_notification(p_business_id UUID,
  p_type TEXT,
  p_title TEXT,
  p_body TEXT DEFAULT NULL,
  p_data JSONB DEFAULT '{}'::jsonb)
RETURNS VOID
AS $guard$

DECLARE
  v_user_id UUID;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN;
  END IF;

  FOR v_user_id IN
    SELECT user_id FROM staff WHERE business_id = p_business_id
  LOOP
    PERFORM send_notification(v_user_id, p_type, p_title, p_body, p_data);
  END LOOP;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.business_relationships(p_business_id UUID, p_start_type TEXT, p_start_id UUID, p_max_depth INTEGER DEFAULT 3)
RETURNS TABLE(entity_type TEXT, entity_id UUID, depth INTEGER, path TEXT[])
AS $guard$

