$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.can_approve(p_business_id UUID, p_staff_id UUID, p_entity_type TEXT, p_amount NUMERIC DEFAULT 0)
RETURNS TABLE(can BOOLEAN, via UUID, approval_limit NUMERIC, reason TEXT)
AS $guard$

DECLARE
  a RECORD; v_limit NUMERIC;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN;
  END IF;

  -- Direct authority.
  SELECT * INTO a FROM authority_graph
  WHERE business_id = p_business_id AND staff_id = p_staff_id
    AND entity_type = p_entity_type AND authority_type = 'approve' AND is_active
    AND (valid_until IS NULL OR valid_until > NOW())
  ORDER BY approval_limit DESC NULLS LAST LIMIT 1;

  IF a.id IS NOT NULL THEN
    v_limit := COALESCE(a.approval_limit, p_amount); -- NULL limit = unlimited
    IF p_amount <= v_limit THEN
      RETURN QUERY SELECT TRUE, a.staff_id, a.approval_limit, 'within direct authority';
      RETURN;
    END IF;
  END IF;

  -- Delegation: someone delegated their authority to this staff member.
  SELECT * INTO a FROM authority_graph
  WHERE business_id = p_business_id AND delegate_to = p_staff_id
    AND entity_type = p_entity_type AND authority_type = 'approve'
    AND delegation_active AND is_active
    AND (valid_until IS NULL OR valid_until > NOW())
  ORDER BY approval_limit DESC NULLS LAST LIMIT 1;

  IF a.id IS NOT NULL THEN
    v_limit := COALESCE(a.approval_limit, p_amount);
    IF p_amount <= v_limit THEN
      RETURN QUERY SELECT TRUE, a.staff_id, a.approval_limit, CONCAT('via delegation from ', a.staff_id);
      RETURN;
    END IF;
  END IF;

  RETURN QUERY SELECT FALSE, NULL::UUID, NULL::NUMERIC, 'no matching authority';
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.cancel_subscription(p_business_id UUID, p_cancel_at_period_end BOOLEAN DEFAULT true)
RETURNS business_subscriptions
AS $guard$

DECLARE
  v_subscription business_subscriptions%ROWTYPE;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  UPDATE business_subscriptions
  SET 
    status = CASE 
      WHEN p_cancel_at_period_end THEN 'active' 
      ELSE 'cancelled' 
    END,
    cancelled_at = NOW(),
    updated_at = NOW()
  WHERE business_id = p_business_id
  RETURNING * INTO v_subscription;
  
  RETURN v_subscription;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.capacity_intelligence(p_business_id UUID)
RETURNS JSONB
AS $guard$

DECLARE
  v_headcount INTEGER; v_open_tasks INTEGER; v_overdue INTEGER;
  v_tasks_per_person NUMERIC; v_overload BOOLEAN;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  SELECT count(*) INTO v_headcount FROM staff WHERE business_id = p_business_id;
  SELECT count(*) FILTER (WHERE status IN ('todo','in_progress')),
         count(*) FILTER (WHERE status IN ('todo','in_progress') AND due_date < CURRENT_DATE)
  INTO v_open_tasks, v_overdue
  FROM tasks WHERE business_id = p_business_id;
  v_tasks_per_person := CASE WHEN v_headcount = 0 THEN 0 ELSE v_open_tasks::NUMERIC / v_headcount END;
  v_overload := v_tasks_per_person > 10 OR v_overdue > v_headcount;
  RETURN jsonb_build_object(
    'signals', jsonb_build_object(
      'headcount', v_headcount,
      'open_tasks', v_open_tasks,
      'overdue_tasks', v_overdue,
      'tasks_per_person', round(v_tasks_per_person::numeric,1),
      'overloaded', v_overload
    ),
    'constraint', CASE WHEN v_overload THEN 'people_capacity' ELSE 'none' END,
    'recommendation', CASE WHEN v_overload THEN 'Consider hiring, outsourcing, or reprioritizing work.' ELSE 'Capacity is balanced.' END,
    'type','INFERENCE'
  );
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.cashflow_forecast_intelligence(p_business_id UUID, p_days INT DEFAULT 30)
RETURNS JSONB
AS $guard$

DECLARE
  v_avg NUMERIC; v_n INTEGER; v_income NUMERIC; v_expense NUMERIC;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(SUM(CASE WHEN type = 'income' THEN amount ELSE 0 END), 0),
         COALESCE(SUM(CASE WHEN type = 'expense' THEN amount ELSE 0 END), 0)
  INTO v_income, v_expense
  FROM cashflow_entries
  WHERE business_id = p_business_id
    AND date >= CURRENT_DATE - INTERVAL '90 days';

  SELECT AVG(daily.net), COUNT(*) INTO v_avg, v_n
  FROM (
    SELECT date, SUM(CASE WHEN type = 'income' THEN amount ELSE -amount END) AS net
    FROM cashflow_entries
    WHERE business_id = p_business_id
      AND date >= CURRENT_DATE - INTERVAL '90 days'
    GROUP BY date
  ) daily;

  IF v_n IS NULL OR v_n < 7 THEN
    RETURN jsonb_build_object(
      'sufficient_data', false,
      'days_of_history', COALESCE(v_n, 0),
      'type', 'ESTIMATE',
      'note', 'Not enough cash-flow history yet (need at least 7 days). Start recording daily cash flow to enable a forecast.'
    );
  END IF;

  RETURN jsonb_build_object(
    'sufficient_data', true,
    'days_of_history', v_n,
    'daily_avg_net', round(v_avg::numeric, 2),
    'projected_net', round((v_avg * p_days)::numeric, 2),
    'horizon_days', p_days,
    'recent_income', v_income,
    'recent_expense', v_expense,
    'method', '90d_moving_average',
    'type', 'ESTIMATE',
    'assumptions', jsonb_build_array(
      'linear projection of the last 90 days of net cash',
      'no seasonality modelled',
      'no growth or decline assumed',
      'excludes unbilled receivables and unpaid payables'
    ),
    'note', 'A deterministic moving-average projection. The narrative "why" stays with a human or a future generative layer.'
  );
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.check_ai_action_authority(p_business_id UUID, p_agent_id UUID, p_capability TEXT, p_rung TEXT)
RETURNS TABLE(allowed BOOLEAN, reason TEXT)
AS $guard$

DECLARE
  v_max TEXT;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN;
  END IF;

  SELECT max_rung INTO v_max FROM ai_capability_authorities
  WHERE business_id = p_business_id AND agent_id = p_agent_id
    AND capability = p_capability AND is_active
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN QUERY SELECT FALSE, 'no authority configured for this capability';
    RETURN;
  END IF;
  IF action_authority_rung_rank(p_rung) > action_authority_rung_rank(v_max) THEN
    RETURN QUERY SELECT FALSE, CONCAT('requested rung ', p_rung, ' exceeds max ', v_max);
    RETURN;
  END IF;
  RETURN QUERY SELECT TRUE, CONCAT('within authority (max ', v_max, ')');
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.check_separation_of_duties(p_business_id UUID, p_staff_id UUID, p_entity_type TEXT,
  p_entity_id UUID, p_action TEXT)
RETURNS TABLE(allowed BOOLEAN, violated_rule TEXT)
AS $guard$

DECLARE
  r RECORD;
  v_prior_actions TEXT[];
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN;
  END IF;

  -- Collect the actions this person already performed on this entity.
  SELECT COALESCE(array_agg(DISTINCT (e.payload->>'action')) FILTER (WHERE e.payload->>'action' IS NOT NULL), '{}'::TEXT[])
  INTO v_prior_actions
  FROM business_events e
  WHERE e.business_id = p_business_id
    AND e.entity_type = p_entity_type AND e.entity_id = p_entity_id
    AND e.payload->>'actor_id' = p_staff_id::TEXT;

  FOR r IN SELECT * FROM separation_of_duties_rules
    WHERE business_id = p_business_id AND entity_type = p_entity_type AND is_active
  LOOP
    IF p_action = ANY(r.incompatible_actions)
       AND array_length(ARRAY(
         SELECT unnest(v_prior_actions) INTERSECT SELECT unnest(r.incompatible_actions)
       ), 1) > 0 THEN
      RETURN QUERY SELECT FALSE, r.description;
      RETURN;
    END IF;
  END LOOP;
  RETURN QUERY SELECT TRUE, NULL::TEXT;
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.company_tree(p_business_id UUID, p_root_id UUID DEFAULT NULL)
RETURNS TABLE(entity_id UUID, name TEXT, entity_type TEXT, parent_entity_id UUID, depth INTEGER, path TEXT)
AS $guard$

BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN;
  END IF;
  RETURN QUERY WITH RECURSIVE walk AS (
  SELECT id, name, entity_type, parent_entity_id, 0 AS depth,
         name::TEXT AS path
  FROM company_entities
  WHERE business_id = p_business_id
    AND (p_root_id IS NULL OR id = p_root_id)
  UNION ALL
  SELECT ce.id, ce.name, ce.entity_type, ce.parent_entity_id, w.depth + 1,
         w.path || ' > ' || ce.name
  FROM company_entities ce JOIN walk w ON ce.parent_entity_id = w.id
  WHERE ce.business_id = p_business_id
)
SELECT * FROM walk ORDER BY depth, name;
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.compensation_review_recommendation(p_business_id UUID, p_staff_id UUID)
RETURNS JSONB
AS $guard$

DECLARE
  s RECORD; v_drivers JSONB; v_recommend BOOLEAN; v_reason TEXT;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  SELECT * INTO s FROM staff WHERE id = p_staff_id AND business_id = p_business_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','staff not found'); END IF;

  -- Drivers are heuristic proxies drawn from real data. Each is labelled
  -- so the recommendation is explainable. Real signal wiring (target
  -- attainment, market benchmark) replaces the proxies as data lands.
  v_drivers := jsonb_build_object(
    'tenure_months', EXTRACT(EPOCH FROM (now() - s.created_at))/2592000,
    'current_salary', s.base_salary,
    'target_attainment', null,
    'market_benchmark', null,
    'internal_equity', null,
    'affordability', null
  );

  -- A simple rule: if tenure > 12 months, flag for review. This is a
  -- RECOMMENDATION, not a decision — the human decides.
  v_recommend := EXTRACT(EPOCH FROM (now() - s.created_at))/2592000 > 12;
  v_reason := CASE WHEN v_recommend
    THEN 'Tenure exceeds 12 months — review recommended. Confirm against target attainment, market and affordability.'
    ELSE 'No review trigger met yet.' END;

  RETURN jsonb_build_object(
    'recommend_review', v_recommend,
    'reason', v_reason,
    'drivers', v_drivers,
    'type', 'RECOMMENDATION',
    'intervention_ladder', jsonb_build_array('observe','diagnose','coach','retrain','improvement_plan','review','authorized_decision')
  );
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.compute_business_health(p_business_id UUID)
RETURNS INTEGER
AS $guard$

DECLARE
  v_dims JSONB := '{}'::JSONB;
  v_overall NUMERIC := 0;
  v_dims_with_data INTEGER := 0;
  v_insufficient TEXT[] := '{}';
  v_dq_penalty INTEGER := 0;
  v_dq_critical INTEGER;
  v_dq_warning INTEGER;
  v_rec_critical INTEGER;
  v_rec JSONB;
  d RECORD;
  m RECORD;
  v_actual NUMERIC;
  v_target NUMERIC;
  v_sub NUMERIC;
  v_dim_score NUMERIC;
  v_dim_weighted NUMERIC;
  v_dim_count INTEGER;
  v_dim_metrics JSONB;
  v_final INTEGER;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  -- For each dimension, average the sub-scores of metrics that have BOTH a
  -- current_value and a target_value (§21: need a target to score against).
  FOR d IN SELECT DISTINCT dimension FROM health_metric_map ORDER BY dimension LOOP
    v_dim_metrics := '[]'::JSONB;
    v_dim_weighted := 0;
    v_dim_count := 0;

    FOR m IN
      SELECT hm.metric_key, hm.direction, hm.label, hm.weight,
             km.current_value, km.target_value
      FROM health_metric_map hm
      LEFT JOIN kpi_metrics km
        ON km.business_id = p_business_id
        AND km.metric_key = hm.metric_key
        AND km.metric_key IS NOT NULL
      WHERE hm.dimension = d.dimension
    LOOP
      -- §21 guard: skip metrics without both actual and target.
      IF m.current_value IS NULL OR m.target_value IS NULL OR m.target_value = 0 THEN
        CONTINUE;
      END IF;

      IF m.direction = 'higher' THEN
        v_sub := LEAST(GREATEST((m.current_value / m.target_value) * 100, 0), 100);
      ELSE -- lower is better: 0 overdue vs target=10 → 100; meeting target → 0
        v_sub := LEAST(GREATEST((1 - (m.current_value / m.target_value)) * 100, 0), 100);
      END IF;

      v_dim_metrics := v_dim_metrics || jsonb_build_array(jsonb_build_object(
        'metric_key', m.metric_key,
        'label', COALESCE(m.label, m.metric_key),
        'actual', m.current_value,
        'target', m.target_value,
        'direction', m.direction,
        'score', round(v_sub::numeric, 1)
      ));
      v_dim_weighted := v_dim_weighted + v_sub * COALESCE(m.weight, 1);
      v_dim_count := v_dim_count + 1;
    END LOOP;

    IF v_dim_count = 0 THEN
      v_insufficient := array_append(v_insufficient, d.dimension);
      v_dims := jsonb_set(v_dims, ARRAY[d.dimension], jsonb_build_object(
        'score', NULL, 'status', 'insufficient_data', 'metrics', '[]'::JSONB
      ));
    ELSE
      v_dim_score := v_dim_weighted / v_dim_count;
      v_dims := jsonb_set(v_dims, ARRAY[d.dimension], jsonb_build_object(
        'score', round(v_dim_score::numeric, 0),
        'status', CASE WHEN v_dim_score >= 80 THEN 'healthy'
                       WHEN v_dim_score >= 60 THEN 'watch'
                       ELSE 'at_risk' END,
        'metrics', v_dim_metrics
      ));
      v_overall := v_overall + v_dim_score;
      v_dims_with_data := v_dims_with_data + 1;
    END IF;
  END LOOP;

  IF v_dims_with_data = 0 THEN
    -- No target-backed metrics at all. Honest: insufficient data (§21).
    v_final := NULL;
  ELSE
    v_overall := v_overall / v_dims_with_data;

    -- Data-quality penalty (089 findings).
    SELECT
      COUNT(*) FILTER (WHERE severity='critical'),
      COUNT(*) FILTER (WHERE severity='warning')
    INTO v_dq_critical, v_dq_warning
    FROM self_audit_findings
    WHERE business_id = p_business_id
      AND audit_dimension = 'data_quality'
      AND resolved = false;

    v_dq_penalty := LEAST(v_dq_critical * 2, 10) + LEAST(v_dq_warning * 1, 5);
    v_overall := GREATEST(v_overall - v_dq_penalty, 0);

    -- Open critical recommendations (flag, don't double-penalize).
    SELECT COUNT(*) INTO v_rec_critical
    FROM claims
    WHERE business_id = p_business_id
      AND claim_type = 'RECOMMENDATION'
      AND severity = 'critical'
      AND status NOT IN ('rejected','outcome_recorded','superseded','expired');

    v_rec := jsonb_build_object('open_critical_recommendations', v_rec_critical);

    v_dims := jsonb_set(v_dims, ARRAY['_meta'], jsonb_build_object(
      'data_quality_penalty', v_dq_penalty,
      'open_critical_findings', v_dq_critical,
      'open_warning_findings', v_dq_warning,
      'recommendations', v_rec
    ));

    v_final := round(v_overall)::INTEGER;
  END IF;

  -- Upsert the latest score.
  INSERT INTO business_health_scores (
    business_id, overall_score, dimension_scores, data_quality_penalty,
    insufficient_dimensions, computed_at
  ) VALUES (
    p_business_id, v_final, v_dims, v_dq_penalty, v_insufficient, NOW()
  )
  ON CONFLICT (business_id) DO UPDATE SET
    overall_score = EXCLUDED.overall_score,
    dimension_scores = EXCLUDED.dimension_scores,
    data_quality_penalty = EXCLUDED.data_quality_penalty,
    insufficient_dimensions = EXCLUDED.insufficient_dimensions,
    computed_at = EXCLUDED.computed_at;

  RETURN v_final;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.continuity_status(p_business_id UUID)
RETURNS JSONB
AS $guard$

DECLARE
  v_last TIMESTAMPTZ; v_count INTEGER; v_tested INTEGER; v_policies JSONB;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  SELECT max(started_at), count(*) INTO v_last, v_count
  FROM backup_runs WHERE business_id = p_business_id AND status='succeeded';
  SELECT count(*) INTO v_tested FROM backup_runs WHERE business_id = p_business_id AND restore_tested;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('category',data_category,'days',retention_days,'basis',basis)), '[]'::JSONB)
  INTO v_policies FROM retention_policies WHERE business_id = p_business_id AND is_active;
  RETURN jsonb_build_object(
    'last_backup_at', v_last,
    'successful_backups', v_count,
    'restore_tests_run', v_tested,
    'retention_policies', v_policies,
    'recommendation', CASE WHEN v_count = 0 THEN 'No successful backup recorded — schedule a backup.'
      WHEN v_tested = 0 THEN 'Backups exist but no restore test has been run — test a restore.'
      ELSE 'Continuity posture looks healthy.' END,
    'type','FACT'
  );
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.convenience_index(p_business_id UUID)
RETURNS TABLE(workflow TEXT, runs INTEGER, avg_ms INTEGER, abandonment NUMERIC, automation_rate NUMERIC)
AS $guard$

BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT workflow,
         count(*)::INTEGER,
         COALESCE(round(avg(time_to_complete_ms))::INTEGER, 0),
         round((1 - (count(*) FILTER (WHERE completed)::NUMERIC / count(*)))::numeric,3),
         round(avg(automation_rate)::numeric,3)
  FROM friction_metrics
  WHERE business_id = p_business_id AND recorded_at > now() - interval '30 days'
  GROUP BY workflow ORDER BY avg_ms DESC NULLS LAST;
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.create_notification(p_user_id UUID,
  p_business_id UUID,
  p_title TEXT,
  p_message TEXT,
  p_category notification_category,
  p_channel notification_channel DEFAULT 'both',
  p_entity_type TEXT DEFAULT NULL,
