  p_action_url TEXT DEFAULT NULL,
  p_action_text TEXT DEFAULT NULL,
  p_scheduled_for TIMESTAMPTZ DEFAULT NULL)
RETURNS UUID
AS $guard$

DECLARE
  v_notification_id UUID;
BEGIN
