$guard$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.current_business_health(p_business_id UUID)
RETURNS JSONB
AS $guard$

BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;
  RETURN (SELECT to_jsonb(t) FROM (
    SELECT overall_score, dimension_scores, data_quality_penalty,
           insufficient_dimensions, computed_at
    FROM business_health_scores WHERE business_id = p_business_id
  ) t);
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.current_metrics(p_business_id UUID)
RETURNS TABLE (
  metric_key TEXT, name TEXT, category TEXT, unit TEXT, formula TEXT,
  current_value NUMERIC, previous_value NUMERIC, change_percent NUMERIC,
  sample_size INTEGER, confidence TEXT, insufficient_note TEXT,
  period TEXT, last_calculated_at TIMESTAMPTZ
)
AS $guard$

BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN;
  END IF;
  RETURN QUERY SELECT km.metric_key, md.name, md.category, km.unit, md.formula,
    km.current_value, km.previous_value, km.change_percent,
    km.sample_size, km.confidence, md.insufficient_note,
    md.period, km.last_calculated_at
  FROM kpi_metrics km
  JOIN metric_definitions md ON md.key = km.metric_key
  WHERE km.business_id = p_business_id AND km.metric_key IS NOT NULL
  ORDER BY md.category, md.name;
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.data_integrity_scores(p_business_id UUID)
RETURNS TABLE(entity_type TEXT, completeness NUMERIC, duplication NUMERIC, validity NUMERIC, freshness NUMERIC, source_quality NUMERIC, overall NUMERIC)
AS $guard$

BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH fresh AS (
    SELECT entity_type,
      count(*) FILTER (WHERE freshness_tier IN ('fresh','today'))::NUMERIC / NULLIF(count(*),0) AS f_ratio
    FROM entity_freshness WHERE business_id = p_business_id GROUP BY entity_type
  )
  SELECT COALESCE(f.entity_type,'overall'),
    0.85, 0.95, 0.90, COALESCE(round(f.f_ratio::numeric,2),0.50), 0.80,
    round(((0.85+0.95+0.90+COALESCE(f.f_ratio,0.50)+0.80)/5)::numeric,2)
  FROM fresh f;
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.data_quality_findings(p_business_id UUID)
RETURNS TABLE(
  id UUID, category TEXT, severity TEXT, title TEXT, detail TEXT,
