$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.early_warnings(p_business_id UUID)
RETURNS JSONB
AS $guard$

DECLARE
  v_warnings JSONB := '[]'::JSONB; v_overdue NUMERIC; v_low_stock INTEGER;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(sum(CASE WHEN status='overdue' THEN total END),0)
  INTO v_overdue FROM invoices WHERE business_id = p_business_id;
  IF v_overdue > 0 THEN
    v_warnings := v_warnings || jsonb_build_object('signal','receivable_aging','value',v_overdue,'severity','warning','note','Overdue receivables growing');
  END IF;
  SELECT count(*) INTO v_low_stock FROM products
  WHERE business_id = p_business_id AND stock <= COALESCE(low_stock_threshold,0);
  IF v_low_stock > 0 THEN
    v_warnings := v_warnings || jsonb_build_object('signal','inventory_shortage','value',v_low_stock,'severity','warning','note','Items at/below reorder');
  END IF;
  RETURN jsonb_build_object('warnings', v_warnings, 'count', jsonb_array_length(v_warnings), 'type','INFERENCE');
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.enforce_approval(p_business_id UUID,
  p_approver_id UUID,
  p_entity_type TEXT,
  p_entity_id UUID,
  p_amount NUMERIC DEFAULT NULL,
  p_blocking BOOLEAN DEFAULT FALSE)
RETURNS TABLE(allowed BOOLEAN, blocked_reasons TEXT[], authority_reason TEXT, sod_reason TEXT)
AS $guard$

DECLARE
  v_auth RECORD; v_sod RECORD;
  v_reasons TEXT[] := '{}'::TEXT[];
  v_auth_ok BOOLEAN := TRUE; v_sod_ok BOOLEAN := TRUE;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN;
  END IF;

  -- §15 Authority: does this person have approval authority + limit?
  SELECT * INTO v_auth FROM can_approve(p_business_id, p_approver_id, p_entity_type, p_amount);
  IF NOT v_auth.can THEN
    v_auth_ok := FALSE;
    v_reasons := array_append(v_reasons, COALESCE(v_auth.reason, 'Insufficient approval authority'));
  END IF;

  -- §22 Separation of duties: did this person create the entity they're approving?
  SELECT * INTO v_sod FROM check_separation_of_duties(p_business_id, p_approver_id, p_entity_type, p_entity_id, 'approve');
  IF NOT v_sod.allowed THEN
    v_sod_ok := FALSE;
    v_reasons := array_append(v_reasons, COALESCE(v_sod.violated_rule, 'Separation of duties violation'));
  END IF;

  -- Audit log regardless of outcome.
  INSERT INTO approval_enforcement_logs (
    business_id, approver_id, entity_type, entity_id, amount,
    authority_ok, authority_reason,
    separation_of_duties_ok, separation_of_duties_reason,
    allowed, blocked_reasons
  ) VALUES (
    p_business_id, p_approver_id, p_entity_type, p_entity_id, p_amount,
    v_auth_ok, v_auth.reason,
    v_sod_ok, v_sod.violated_rule,
    (v_auth_ok AND v_sod_ok), v_reasons
  );

  IF p_blocking AND NOT (v_auth_ok AND v_sod_ok) THEN
    RAISE EXCEPTION 'Approval blocked: %', array_to_string(v_reasons, '; ');
  END IF;

  RETURN QUERY SELECT (v_auth_ok AND v_sod_ok), v_reasons, v_auth.reason, v_sod.violated_rule;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.financial_health_index(p_business_id UUID)
RETURNS JSONB
AS $guard$

DECLARE
  v_receivables NUMERIC; v_overdue NUMERIC; v_paid NUMERIC; v_coverage NUMERIC;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(sum(CASE WHEN status IN ('sent','overdue') THEN total END),0),
         COALESCE(sum(CASE WHEN status='overdue' THEN total END),0),
         COALESCE(sum(CASE WHEN status='paid' THEN total END),0)
  INTO v_receivables, v_overdue, v_paid
  FROM invoices WHERE business_id = p_business_id;
  v_coverage := CASE WHEN v_receivables = 0 THEN 100 ELSE 100 - ((v_overdue / NULLIF(v_receivables,0)) * 100) END;
  RETURN jsonb_build_object(
    'signals', jsonb_build_object(
      'receivables', v_receivables,
      'overdue_receivables', v_overdue,
      'collected', v_paid,
      'collection_coverage', v_coverage
    ),
    'score', GREATEST(0, LEAST(100, v_coverage::INTEGER)),
    'components', jsonb_build_array('receivables','overdue','collection_coverage')
  );
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

