CREATE OR REPLACE FUNCTION public.get_org_chart(p_business_id UUID)
RETURNS TABLE(
  staff_id UUID,
  name TEXT,
  email TEXT,
  job_title TEXT,
  department TEXT,
  role TEXT,
  avatar_url TEXT,
  reports_to UUID,
  level INTEGER
)
AS $guard$

BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT 
    s.id as staff_id,
    s.name,
    s.email,
    s.job_title,
    s.department,
    s.role,
    s.avatar_url,
    ra.staff_id as reports_to,
    COALESCE(s.level, 0) as level
  FROM staff s
  LEFT JOIN reporting_channels rc ON rc.staff_id = s.id
  LEFT JOIN reporting_assignments ra ON ra.channel_id = rc.channel_id AND ra.is_primary = TRUE
  WHERE s.business_id = p_business_id
    AND s.is_active = TRUE
  ORDER BY s.level NULLS LAST, s.name;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.get_public_profile(p_business_id UUID)
RETURNS JSONB
AS $guard$

DECLARE
  v_result JSONB;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  SELECT jsonb_build_object(
    'business_id', b.id,
    'brand_name', COALESCE(bb.brand_name, b.name),
    'tagline', bb.tagline,
    'logo_url', bb.logo_url,
    'primary_color', bb.primary_color,
    'portfolio_items', (
      SELECT jsonb_agg(jsonb_build_object(
        'title', pi.title,
        'short_description', pi.short_description,
        'cover_image_url', pi.cover_image_url,
        'category', pi.category
      ) ORDER BY pi.order_index)
      FROM portfolio_items pi
      WHERE pi.business_id = b.id AND pi.status = 'active'
    ),
    'team', (
      SELECT jsonb_agg(jsonb_build_object(
        'full_name', pt.full_name,
        'title', pt.title,
        'avatar_url', pt.avatar_url,
        'expertise', pt.expertise
      ) ORDER BY pt.order_index)
      FROM portfolio_team pt
      WHERE pt.business_id = b.id
    ),
    'testimonials', (
      SELECT jsonb_agg(jsonb_build_object(
        'client_name', t.client_name,
        'client_company', t.client_company,
        'content', t.content,
        'rating', t.rating
      ) ORDER BY t.order_index)
      FROM testimonials t
      WHERE t.business_id = b.id AND t.is_published = TRUE
    )
  ) INTO v_result
  FROM businesses b
  LEFT JOIN business_branding bb ON bb.business_id = b.id
  WHERE b.id = p_business_id;

  RETURN v_result;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

