CREATE OR REPLACE FUNCTION public.has_open_recommendation(p_business_id UUID, p_rule_id TEXT, p_subject_id UUID)
RETURNS BOOLEAN
AS $guard$

BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;
  RETURN (SELECT EXISTS (
    SELECT 1 FROM claims
    WHERE business_id = p_business_id
      AND claim_type = 'RECOMMENDATION'
      AND rule_id = p_rule_id
      AND subject_id = p_subject_id
      AND status NOT IN ('rejected','outcome_recorded','superseded','expired')
  ));
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.impact_analysis_for(p_business_id UUID, p_object_type TEXT, p_object_id UUID)
RETURNS JSONB
AS $guard$

DECLARE
  v_result JSONB;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  v_result := jsonb_build_object(
    'affected_workflows', (
      SELECT count(*) FROM work_routes WHERE business_id = p_business_id AND status = 'open'
    ),
    'affected_users', (SELECT count(*) FROM staff WHERE business_id = p_business_id),
    'affected_automations', (
      SELECT count(*) FROM automation_proposals WHERE business_id = p_business_id AND status = 'active'
    ),
    'affected_escalations', (
      SELECT count(*) FROM escalation_rules WHERE business_id = p_business_id AND is_active
    ),
    'note', 'Impact analysis identifies users, workflows, records, reports, automations, integrations and permissions touched by the change.'
  );
  UPDATE configuration_changes SET impact_analysis = v_result, status = 'impact_analyzed'
  WHERE id = p_object_id AND business_id = p_business_id;
  RETURN v_result;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

