CREATE OR REPLACE FUNCTION public.is_feature_enabled(p_business_id UUID, p_flag_key TEXT)
RETURNS BOOLEAN
AS $guard$

DECLARE
  v_enabled BOOLEAN; v_shutdown BOOLEAN; v_pct INTEGER; v_hash INTEGER;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  SELECT enabled, emergency_shutdown, rollout_pct INTO v_enabled, v_shutdown, v_pct
  FROM feature_flags
  WHERE (business_id IS NULL OR business_id = p_business_id) AND flag_key = p_flag_key
  ORDER BY business_id NULLS LAST LIMIT 1;
  IF NOT FOUND THEN RETURN FALSE; END IF;
  IF v_shutdown THEN RETURN FALSE; END IF;
  IF NOT v_enabled THEN RETURN FALSE; END IF;
  -- Deterministic per-business rollout hash.
  v_hash := abs(hashtext(p_business_id::TEXT || p_flag_key)) % 100;
  RETURN v_hash < v_pct;
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.issue_recommendation(p_business_id UUID,
  p_rule_id TEXT,
  p_severity TEXT,
  p_subject_type TEXT,
  p_subject_id UUID,
  p_statement TEXT,
  p_evidence JSONB,
  p_expected_impact JSONB,
  p_confidence NUMERIC DEFAULT 0.7)
RETURNS UUID
AS $guard$

DECLARE
  v_id UUID;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  IF p_subject_id IS NOT NULL AND has_open_recommendation(p_business_id, p_rule_id, p_subject_id) THEN
    SELECT id INTO v_id FROM claims
      WHERE business_id = p_business_id AND claim_type='RECOMMENDATION' AND rule_id = p_rule_id
        AND subject_id = p_subject_id
        AND status NOT IN ('rejected','outcome_recorded','superseded','expired')
      LIMIT 1;
    RETURN v_id;
  END IF;
  INSERT INTO claims (
    business_id, claim_type, status, rule_id, severity,
    subject_type, subject_id, statement, evidence, confidence,
    expected_impact
  ) VALUES (
    p_business_id, 'RECOMMENDATION', 'issued', p_rule_id, p_severity,
    p_subject_type, p_subject_id, p_statement, p_evidence, p_confidence,
    p_expected_impact
  )
  ON CONFLICT DO NOTHING
  RETURNING id INTO v_id;
  RETURN v_id;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.knowledge_concentration(p_business_id UUID)
RETURNS JSONB
AS $guard$

DECLARE
  v_rows JSONB;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object('decided_by', decided_by, 'decision_count', cnt)), '[]'::JSONB)
  INTO v_rows FROM (
    SELECT decided_by, count(*) AS cnt
    FROM decisions WHERE business_id = p_business_id AND decided_by IS NOT NULL
    GROUP BY decided_by HAVING count(*) > 3
    ORDER BY cnt DESC
  ) t;
  RETURN jsonb_build_object('concentrated_owners', v_rows, 'risk',
    CASE WHEN jsonb_array_length(v_rows) > 0 THEN 'knowledge concentrated in few people — capture and delegate' ELSE 'balanced' END,
    'type','INFERENCE');
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.link_entities(p_business_id UUID, p_source_type TEXT, p_source_id UUID,
  p_relationship TEXT, p_target_type TEXT, p_target_id UUID,
  p_origin TEXT DEFAULT 'derived', p_confidence NUMERIC DEFAULT NULL,
  p_metadata JSONB DEFAULT '{}'::JSONB)
RETURNS VOID
AS $guard$

BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN;
  END IF;

  INSERT INTO entity_relationships (business_id, source_type, source_id,
    relationship, target_type, target_id, origin, confidence, metadata)
  VALUES (p_business_id, p_source_type, p_source_id, p_relationship,
    p_target_type, p_target_id, p_origin, p_confidence, p_metadata)
  ON CONFLICT (business_id, source_type, source_id, relationship, target_type, target_id)
  DO UPDATE SET metadata = EXCLUDED.metadata, confidence = COALESCE(EXCLUDED.confidence, entity_relationships.confidence);
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

