CREATE OR REPLACE FUNCTION public.record_audit(p_business_id UUID,
  p_user_id UUID,
  p_action TEXT,
  p_entity_type TEXT,
  p_entity_id UUID,
  p_old_values JSONB DEFAULT NULL,
  p_new_values JSONB DEFAULT NULL)
RETURNS UUID
AS $guard$

DECLARE
  v_changed_fields TEXT[];
  v_log_id UUID;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  -- Calculate changed fields
  IF p_old_values IS NOT NULL AND p_new_values IS NOT NULL THEN
    SELECT array_agg(key)
    INTO v_changed_fields
    FROM jsonb_object_keys(p_old_values) AS key
    WHERE p_old_values->>key IS DISTINCT FROM p_new_values->>key;
  END IF;
  
  INSERT INTO audit_logs (
    business_id, user_id, action, entity_type, entity_id,
    old_values, new_values, changed_fields
  ) VALUES (
    p_business_id, p_user_id, p_action, p_entity_type, p_entity_id,
    p_old_values, p_new_values, v_changed_fields
  ) RETURNING id INTO v_log_id;
  
  RETURN v_log_id;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.record_reconciliation(p_business_id UUID, p_metric TEXT, p_sources JSONB, p_tolerance NUMERIC DEFAULT 0)
RETURNS UUID
AS $guard$

DECLARE
  v_values NUMERIC[]; v_max NUMERIC; v_min NUMERIC; v_delta NUMERIC; v_status TEXT;
  v_keys TEXT[]; v_id UUID;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  SELECT array_agg((value->>0)::NUMERIC) INTO v_values
  FROM jsonb_each(p_sources);
  v_max := array_max(v_values);
  v_min := array_min(v_values);
  v_delta := v_max - v_min;
  IF v_max IS NULL THEN v_status := 'missing';
  ELSIF v_delta > p_tolerance THEN v_status := 'conflict';
  ELSE v_status := 'ok'; END IF;

  INSERT INTO data_quality_checks (business_id, metric, sources, status, max_delta)
  VALUES (p_business_id, p_metric, p_sources, v_status, v_delta)
  RETURNING id INTO v_id;
  RETURN v_id;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.recursive_neighbors(p_business_id UUID,
  p_start_type TEXT,
  p_start_id UUID,
  p_max_depth INTEGER DEFAULT 3)
RETURNS TABLE(entity_type TEXT, entity_id UUID, depth INTEGER, path TEXT[])
AS $guard$

BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN;
  END IF;
  RETURN QUERY WITH RECURSIVE walk AS (
  SELECT source_type, source_id, target_type, target_id, relationship, 1 AS depth,
         ARRAY[source_type||':'||source_id, relationship, target_type||':'||target_id] AS path
  FROM entity_relationships
  WHERE business_id = p_business_id
    AND source_type = p_start_type AND source_id = p_start_id
  UNION
  SELECT er.source_type, er.source_id, er.target_type, er.target_id, er.relationship, w.depth + 1,
         w.path || er.relationship || (er.target_type||':'||er.target_id)
  FROM entity_relationships er
  JOIN walk w ON w.target_type = er.source_type AND w.target_id = er.source_id
  WHERE er.business_id = p_business_id AND w.depth < p_max_depth
)
SELECT DISTINCT target_type, target_id, depth, path FROM walk
UNION
SELECT p_start_type, p_start_id, 0, ARRAY[p_start_type||':'||p_start_id];
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.refresh_business_metrics(p_business_id UUID)
RETURNS TABLE(metric_key TEXT, status TEXT, sample_size INTEGER)
AS $guard$

DECLARE
  v_now TIMESTAMPTZ := NOW();
  v_today DATE := CURRENT_DATE;
  v_period_end DATE := v_today;
  v_prev_end DATE := v_today - 1;
  v_cur_start DATE;
  v_prev_start DATE;
  v_def RECORD;
  v_val NUMERIC; v_prev NUMERIC; v_n INTEGER; v_src JSONB;
  v_conf TEXT;
  v_90 DATE := v_today - 90;
  v_180 DATE := v_today - 180;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN;
  END IF;

  FOR v_def IN SELECT * FROM metric_definitions WHERE is_active LOOP
    v_val := NULL; v_prev := NULL; v_n := 0; v_src := '{}'::JSONB; v_conf := NULL;
    BEGIN
      -- Point-in-time vs trailing-window periods.
      IF v_def.period = 'point_in_time' THEN
        v_cur_start := v_today; v_prev_start := v_today - 1; v_prev_end := v_today - 1;
      ELSIF v_def.period = 'trailing_30d' THEN
        v_cur_start := v_today - 30; v_prev_start := v_today - 60; v_prev_end := v_today - 31;
      ELSIF v_def.period = 'trailing_365d' THEN
        v_cur_start := v_today - 365; v_prev_start := v_today - 730; v_prev_end := v_today - 366;
      ELSIF v_def.period = 'all_time' THEN
        v_cur_start := DATE '1900-01-01'; v_prev_start := DATE '1900-01-01'; v_prev_end := DATE '1900-01-01';
      ELSE -- trailing_90d
        v_cur_start := v_90; v_prev_start := v_180; v_prev_end := v_today - 91;
      END IF;

      -- ---- per-metric calculation (current + previous + sample) ----
      IF v_def.key = 'revenue_collected' THEN
        SELECT COALESCE(SUM(total),0), COUNT(*) INTO v_val, v_n
        FROM invoices WHERE business_id = p_business_id
          AND lower(status) = 'paid' AND created_at::date >= v_cur_start;
        SELECT COALESCE(SUM(total),0) INTO v_prev
        FROM invoices WHERE business_id = p_business_id
          AND lower(status) = 'paid'
          AND created_at::date >= v_prev_start AND created_at::date <= v_prev_end;

      ELSIF v_def.key = 'revenue_billed' THEN
        SELECT COALESCE(SUM(total),0), COUNT(*) INTO v_val, v_n
        FROM invoices WHERE business_id = p_business_id
          AND lower(status) IN ('sent','overdue','paid') AND created_at::date >= v_cur_start;
        SELECT COALESCE(SUM(total),0) INTO v_prev
        FROM invoices WHERE business_id = p_business_id
          AND lower(status) IN ('sent','overdue','paid')
          AND created_at::date >= v_prev_start AND created_at::date <= v_prev_end;

      ELSIF v_def.key = 'receivables_outstanding' THEN
        SELECT COALESCE(SUM(total),0), COUNT(*) INTO v_val, v_n
        FROM invoices WHERE business_id = p_business_id
          AND lower(status) IN ('sent','overdue');

      ELSIF v_def.key = 'overdue_receivables' THEN
        SELECT COALESCE(SUM(total),0), COUNT(*) INTO v_val, v_n
        FROM invoices WHERE business_id = p_business_id AND lower(status) = 'overdue';

      ELSIF v_def.key = 'overdue_receivables_pct' THEN
        SELECT COALESCE(SUM(CASE WHEN lower(status)='overdue' THEN total ELSE 0 END),0),
               COALESCE(SUM(CASE WHEN lower(status) IN ('sent','overdue') THEN total ELSE 0 END),0),
               COUNT(*) INTO v_val, v_prev, v_n
        FROM invoices WHERE business_id = p_business_id;
        IF v_prev > 0 THEN v_val := (v_val / v_prev) * 100; ELSE v_val := NULL; END IF;
        v_prev := NULL;

      ELSIF v_def.key = 'collection_rate' THEN
        SELECT COALESCE(SUM(CASE WHEN lower(status)='paid' THEN total ELSE 0 END),0),
               COALESCE(SUM(total),0), COUNT(*) INTO v_val, v_prev, v_n
        FROM invoices WHERE business_id = p_business_id
          AND lower(status) IN ('sent','overdue','paid') AND created_at::date >= v_cur_start;
        IF v_prev > 0 THEN v_val := (v_val / v_prev) * 100; ELSE v_val := NULL; END IF;
        v_prev := NULL;

      ELSIF v_def.key = 'avg_collection_period_days' THEN
        SELECT COALESCE(AVG(EXTRACT(EPOCH FROM (p.created_at - i.created_at))/86400),0), COUNT(*)
        INTO v_val, v_n
        FROM payments p JOIN invoices i ON i.id = p.invoice_id
        WHERE i.business_id = p_business_id
          AND lower(p.status) IN ('successful','paid','completed','success')
          AND p.created_at::date >= v_cur_start;

      ELSIF v_def.key = 'pipeline_value' THEN
        SELECT COALESCE(SUM(value),0), COUNT(*) INTO v_val, v_n
        FROM deals WHERE business_id = p_business_id
          AND lower(stage) NOT IN ('won','lost','closed_won','closed-won');

      ELSIF v_def.key = 'win_rate' THEN
        SELECT COUNT(*) FILTER (WHERE lower(stage) IN ('won','closed_won','closed-won')),
               COUNT(*) FILTER (WHERE lower(stage) IN ('won','lost','closed_won','closed-won','closed-lost')),
               COUNT(*) FILTER (WHERE lower(stage) IN ('won','lost','closed_won','closed-won','closed-lost'))
        INTO v_val, v_prev, v_n
        FROM deals WHERE business_id = p_business_id
          AND lower(stage) IN ('won','lost','closed_won','closed-won','closed-lost')
          AND created_at::date >= v_cur_start;
        IF v_n > 0 THEN v_val := (v_val / v_n) * 100; ELSE v_val := NULL; END IF;
        v_prev := NULL;

      ELSIF v_def.key = 'avg_deal_value' THEN
        SELECT COALESCE(AVG(value),0), COUNT(*) INTO v_val, v_n
        FROM deals WHERE business_id = p_business_id
          AND lower(stage) IN ('won','closed_won','closed-won')
          AND created_at::date >= v_cur_start;
        SELECT COALESCE(AVG(value),0) INTO v_prev
        FROM deals WHERE business_id = p_business_id
          AND lower(stage) IN ('won','closed_won','closed-won')
          AND created_at::date >= v_prev_start AND created_at::date <= v_prev_end;

      ELSIF v_def.key = 'sales_cycle_days' THEN
        SELECT COALESCE(AVG(EXTRACT(EPOCH FROM (updated_at - created_at))/86400),0), COUNT(*)
        INTO v_val, v_n
        FROM deals WHERE business_id = p_business_id
          AND lower(stage) IN ('won','closed_won','closed-won')
          AND created_at::date >= v_cur_start;

      ELSIF v_def.key = 'revenue_concentration_top1' THEN
        SELECT COALESCE(MAX(c.total) / NULLIF(SUM(c.total),0) * 100, 0), COUNT(*)
        INTO v_val, v_n
        FROM (
          SELECT COALESCE(NULLIF(client_name,''), 'unknown') AS cust, SUM(total) AS total
          FROM invoices WHERE business_id = p_business_id
            AND lower(status) IN ('sent','overdue','paid') AND created_at::date >= v_cur_start
          GROUP BY COALESCE(NULLIF(client_name,''), 'unknown')
        ) c;

      ELSIF v_def.key = 'customer_count' THEN
        SELECT COUNT(DISTINCT COALESCE(NULLIF(client_name,''), client_email)) INTO v_val
        FROM invoices WHERE business_id = p_business_id
          AND lower(status) IN ('sent','overdue','paid') AND created_at::date >= v_cur_start;
        v_n := v_val;

      ELSIF v_def.key = 'task_completion_rate' THEN
        SELECT COUNT(*) FILTER (WHERE lower(status) IN ('done','completed')),
               COUNT(*)
        INTO v_val, v_n
        FROM tasks WHERE business_id = p_business_id
          AND created_at::date >= v_cur_start;
        IF v_n > 0 THEN v_val := (v_val / v_n) * 100; ELSE v_val := NULL; END IF;

      ELSIF v_def.key = 'task_overdue_count' THEN
        SELECT COUNT(*), COUNT(*) INTO v_val, v_n
        FROM tasks WHERE business_id = p_business_id
          AND lower(status) IN ('todo','in_progress') AND due_date IS NOT NULL AND due_date < v_today;

      ELSIF v_def.key = 'inventory_low_count' THEN
        SELECT COUNT(*), COUNT(*) INTO v_val, v_n
        FROM products WHERE business_id = p_business_id
          AND stock <= COALESCE(low_stock_threshold, 0);

      ELSIF v_def.key = 'inventory_turnover_proxy' THEN
        SELECT COUNT(DISTINCT ti.product_id), COUNT(*) INTO v_val, v_n
        FROM transaction_items ti
        JOIN transactions t ON t.id = ti.transaction_id
        WHERE t.business_id = p_business_id
          AND lower(t.type) IN ('sale','return')
          AND t.created_at::date >= v_cur_start;

      ELSIF v_def.key = 'headcount' THEN
        SELECT COUNT(*), COUNT(*) INTO v_val, v_n
        FROM staff WHERE business_id = p_business_id;

      ELSIF v_def.key = 'project_active_count' THEN
        SELECT COUNT(*), COUNT(*) INTO v_val, v_n
        FROM projects WHERE business_id = p_business_id AND lower(status) = 'active';

      ELSIF v_def.key = 'data_quality_score' THEN
        SELECT COUNT(*) FILTER (WHERE client_name IS NOT NULL AND client_name <> '' AND due_date IS NOT NULL),
               COUNT(*)
        INTO v_val, v_n
        FROM invoices WHERE business_id = p_business_id;
        IF v_n > 0 THEN v_val := (v_val / v_n) * 100; ELSE v_val := NULL; END IF;
      END IF;

      -- Confidence / insufficient-data classification (§10/§21).
      IF v_n IS NULL OR v_n = 0 THEN
        v_val := NULL; v_conf := 'insufficient';
      ELSIF v_n < v_def.min_sample THEN
        v_val := NULL; v_conf := 'insufficient';
      ELSIF v_n < v_def.min_sample * 2 THEN
        v_conf := 'low';
      ELSIF v_n < v_def.min_sample * 5 THEN
        v_conf := 'medium';
      ELSE
        v_conf := 'high';
      END IF;

      -- Idempotent upsert into kpi_metrics.
      INSERT INTO kpi_metrics (
        business_id, metric_key, name, category, unit, data_source,
        current_value, previous_value, change_value, change_percent,
        sample_size, confidence, period_start, period_end,
        source_detail, last_calculated_at, query_definition
      ) VALUES (
        p_business_id, v_def.key, v_def.name, v_def.category, v_def.unit, v_def.sources::TEXT,
        v_val, v_prev,
        CASE WHEN v_val IS NOT NULL AND v_prev IS NOT NULL THEN v_val - v_prev END,
        CASE WHEN v_val IS NOT NULL AND v_prev IS NOT NULL AND v_prev <> 0
          THEN round(((v_val - v_prev) / abs(v_prev) * 100)::numeric, 2) END,
        v_n, v_conf, v_cur_start, v_period_end,
        jsonb_build_object('sources', v_def.sources, 'formula', v_def.formula, 'period', v_def.period),
        v_now, jsonb_build_object('version', v_def.version)
      )
      ON CONFLICT (business_id, metric_key, period_end)
      DO UPDATE SET
        current_value = EXCLUDED.current_value,
        previous_value = EXCLUDED.previous_value,
        change_value = EXCLUDED.change_value,
        change_percent = EXCLUDED.change_percent,
        sample_size = EXCLUDED.sample_size,
        confidence = EXCLUDED.confidence,
        period_start = EXCLUDED.period_start,
        source_detail = EXCLUDED.source_detail,
        last_calculated_at = EXCLUDED.last_calculated_at,
        data_source = EXCLUDED.data_source;

      metric_key := v_def.key;
      status := v_conf;
      sample_size := COALESCE(v_n, 0);
      RETURN NEXT;

    EXCEPTION WHEN OTHERS THEN
      -- A single broken metric never aborts the refresh, never corrupts
      -- business data, and never blocks operations (§24). Report + continue.
      metric_key := v_def.key;
      status := 'error';
      sample_size := 0;
      RETURN NEXT;
    END;
  END LOOP;
  RETURN;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.resolve_canonical(p_business_id UUID, p_alias TEXT)
RETURNS TABLE(canonical_type TEXT, canonical_table TEXT)
AS $guard$

BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN;
  END IF;
  RETURN QUERY SELECT canonical_type, canonical_table FROM business_ontology
WHERE business_id = p_business_id AND lower(alias) = lower(p_alias)
LIMIT 1;
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.resolve_payment_provider(p_business_id UUID, p_currency TEXT)
RETURNS TABLE(id UUID, provider TEXT)
AS $guard$

DECLARE
  v_default UUID;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN;
  END IF;

  SELECT id INTO v_default FROM payment_providers
  WHERE business_id = p_business_id AND is_active AND is_default
  ORDER BY created_at LIMIT 1;

  IF v_default IS NOT NULL THEN
    RETURN QUERY SELECT pp.id, pp.provider FROM payment_providers pp
    WHERE pp.id = v_default;
    RETURN;
  END IF;

  -- Fall back to the first active provider that lists the currency.
  RETURN QUERY SELECT pp.id, pp.provider FROM payment_providers pp
  WHERE pp.business_id = p_business_id AND pp.is_active
    AND (p_currency = ANY(pp.supported_currencies) OR array_length(pp.supported_currencies,1) IS NULL)
  ORDER BY pp.created_at LIMIT 1;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.revenue_forecast(p_business_id UUID, p_horizon_months INTEGER DEFAULT 3)
RETURNS JSONB
AS $guard$

DECLARE
  v_collected NUMERIC; v_receivables NUMERIC; v_proj NUMERIC; v_months INTEGER;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(sum(CASE WHEN status='paid' THEN total END),0),
         COALESCE(sum(CASE WHEN status IN ('sent','overdue') THEN total END),0),
         count(*) FILTER (WHERE status='paid')
  INTO v_collected, v_receivables, v_months
  FROM invoices WHERE business_id = p_business_id;

  v_proj := (v_collected / NULLIF(greatest(v_months,1),0)) * p_horizon_months;
  RETURN jsonb_build_object(
    'monthly_avg_collected', round((v_collected / NULLIF(greatest(v_months,1),0))::numeric,0),
    'projected_next_months', round(v_proj::numeric,0),
    'horizon_months', p_horizon_months,
    'receivables_in_flight', v_receivables,
    'assumptions', jsonb_build_array('linear projection of historical collection','no seasonality modeled','no growth assumed'),
    'confidence', CASE WHEN v_months >= 3 THEN 0.7 WHEN v_months >= 1 THEN 0.4 ELSE 0.2 END,
    'type','ESTIMATE'
  );
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.risk_anomaly_intelligence(p_business_id UUID)
RETURNS JSONB
AS $guard$

DECLARE
  v_dup_invoices JSONB; v_concentration JSONB; v_anomalies JSONB;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  -- Duplicate invoice amounts (same total, same contact, within 30 days).
  SELECT COALESCE(jsonb_agg(jsonb_build_object('total', total, 'contact_id', contact_id, 'count', cnt)), '[]'::JSONB)
  INTO v_dup_invoices
  FROM (
    SELECT total, contact_id, count(*) AS cnt
    FROM invoices WHERE business_id = p_business_id
    GROUP BY total, contact_id HAVING count(*) > 1
  ) d;

  -- Customer concentration: any single contact > 50% of billed revenue.
  SELECT COALESCE(jsonb_agg(jsonb_build_object('contact_id', contact_id, 'share_pct', round(share*100,1))), '[]'::JSONB)
  INTO v_concentration
  FROM (
    SELECT contact_id, sum(total) / NULLIF(sum(sum(total)) OVER (), 0) AS share
    FROM invoices WHERE business_id = p_business_id AND contact_id IS NOT NULL
    GROUP BY contact_id
  ) c WHERE share > 0.5;

  v_anomalies := jsonb_build_array();
  IF jsonb_array_length(v_dup_invoices) > 0 THEN
    v_anomalies := v_anomalies || jsonb_build_object('type','duplicate_invoice_amounts','detail',v_dup_invoices,'severity','warning');
  END IF;
  IF jsonb_array_length(v_concentration) > 0 THEN
    v_anomalies := v_anomalies || jsonb_build_object('type','customer_concentration','detail',v_concentration,'severity','warning');
  END IF;

  RETURN jsonb_build_object(
    'anomalies', v_anomalies,
    'count', jsonb_array_length(v_anomalies),
    'note', 'Patterns flagged for investigation only; not accusations of wrongdoing.',
    'type','INFERENCE'
  );
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.risk_summary(p_business_id UUID)
RETURNS JSONB
AS $guard$

BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;
  RETURN (SELECT jsonb_build_object(
    'total', count(*),
    'open', count(*) FILTER (WHERE status = 'open'),
    'high', count(*) FILTER (WHERE risk_score >= 15),
    'by_category', COALESCE(
      (SELECT jsonb_object_agg(category, cat_data)
       FROM (
         SELECT category, jsonb_build_object(
           'total', count(*),
           'open', count(*) FILTER (WHERE status = 'open'),
           'avg_score', round(avg(risk_score)::numeric, 1)
         ) AS cat_data
         FROM business_risks
         WHERE business_id = p_business_id
         GROUP BY category
       ) sub),
      '{}'::jsonb
    )
  )
  FROM business_risks
  WHERE business_id = p_business_id);
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.route_work(p_business_id UUID, p_request_type TEXT, p_entity_type TEXT, p_entity_id UUID)
RETURNS UUID
AS $guard$

DECLARE
  v_route_id UUID; v_approver UUID;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  -- Find the first active approver for this entity type in authority_graph.
  SELECT staff_id INTO v_approver FROM authority_graph
  WHERE business_id = p_business_id AND entity_type = p_entity_type
    AND authority_type = 'approve' AND is_active
  ORDER BY approval_limit DESC NULLS LAST LIMIT 1;

  INSERT INTO work_routes (business_id, request_type, entity_type, entity_id,
    owner_id, approver_id, status, created_at)
  VALUES (p_business_id, p_request_type, p_entity_type, p_entity_id,
    v_approver, v_approver, 'open', NOW())
  RETURNING id INTO v_route_id;

  RETURN v_route_id;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.run_agent_guardrail(p_business_id UUID, p_agent_id UUID, p_capability TEXT, p_rung TEXT,
  p_policy JSONB DEFAULT '{}'::JSONB, p_requires_simulation BOOLEAN DEFAULT FALSE)
RETURNS UUID
AS $guard$

DECLARE
  v_id UUID; v_auth RECORD; v_passed BOOLEAN := TRUE; v_reason TEXT;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  INSERT INTO agent_guardrail_checks (business_id, agent_id, capability, attempted_rung, created_at)
  VALUES (p_business_id, p_agent_id, p_capability, p_rung, NOW())
  RETURNING id INTO v_id;

  -- Authority check.
  SELECT * INTO v_auth FROM check_ai_action_authority(p_business_id, p_agent_id, p_capability, p_rung);
  IF NOT v_auth.allowed THEN
    v_passed := FALSE; v_reason := v_auth.reason;
  END IF;

  UPDATE agent_guardrail_checks SET
    identity_ok = TRUE,
    authority_ok = v_auth.allowed,
    policy_ok = v_passed,
    risk_ok = v_passed,
    validation_ok = v_passed,
    simulation_ok = CASE WHEN p_requires_simulation THEN v_passed ELSE TRUE END,
    execution_ok = v_passed,
    verification_ok = v_passed,
    audit_ok = TRUE,
    passed = v_passed,
    blocked_reason = v_reason
  WHERE id = v_id;

  RETURN v_id;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.run_behavior_recommendation_rules(p_business_id UUID)
RETURNS TABLE(rule_id TEXT, issued_count INTEGER)
AS $guard$

DECLARE
  v_n INTEGER;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN;
  END IF;

  -- USAGE-001 (#17): Modules selected but never used in 30 days.
  -- "You selected X at setup but your team hasn't used it. Consider removing
  -- it to simplify your workspace, or explore why it isn't sticking."
  BEGIN
    WITH selected_unused AS (
      SELECT unnest(COALESCE(uws.selected_tools, '{}'::TEXT[])) AS module_key
      FROM user_workspace_selections uws
      WHERE uws.business_id = p_business_id
        AND uws.selection_completed = true
      EXCEPT
      SELECT DISTINCT ue.module_key
      FROM usage_events ue
      WHERE ue.business_id = p_business_id
        AND ue.occurred_at >= NOW() - INTERVAL '30 days'
    )
    INSERT INTO claims (business_id, claim_type, status, rule_id, severity,
      subject_type, subject_id, statement, evidence, confidence, expected_impact)
    SELECT p_business_id, 'RECOMMENDATION', 'issued', 'USAGE-001', 'info',
      'module', NULL,
      'You selected "' || su.module_key || '" during setup, but your team has
        not used it in the last 30 days. Consider removing it from your workspace
        to reduce clutter, or explore why it isn''t being adopted.',
      jsonb_build_object('module_key', su.module_key, 'days_unused', 30,
        'source', 'workspace_selection_vs_usage_events'),
      0.6,
      jsonb_build_object('description', 'Simpler workspace, less clutter')
    FROM selected_unused su
    WHERE NOT has_open_recommendation(p_business_id, 'USAGE-001', NULL)
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    rule_id := 'USAGE-001'; issued_count := v_n; RETURN NEXT;
  EXCEPTION WHEN OTHERS THEN
    rule_id := 'USAGE-001'; issued_count := 0; RETURN NEXT;
  END;

  -- USAGE-002 (#17): Workflow abandonment — a workflow with > 50% abandonment.
  -- "Your team started N quote workflows but only completed M. Review where
  -- they stall." §21 guard: >= 3 starts (enough to call it a pattern).
  BEGIN
    WITH wf_stats AS (
      SELECT
        ue.context->>'workflow' AS wf,
        COUNT(*) FILTER (WHERE ue.action = 'workflow_start') AS started,
        COUNT(*) FILTER (WHERE ue.action = 'workflow_complete') AS completed
      FROM usage_events ue
      WHERE ue.business_id = p_business_id
        AND ue.occurred_at >= NOW() - INTERVAL '30 days'
        AND ue.action IN ('workflow_start', 'workflow_complete')
        AND ue.context ? 'workflow'
      GROUP BY ue.context->>'workflow'
    )
    INSERT INTO claims (business_id, claim_type, status, rule_id, severity,
      subject_type, subject_id, statement, evidence, confidence, expected_impact)
    SELECT p_business_id, 'RECOMMENDATION', 'issued', 'USAGE-002', 'warning',
      'workflow', NULL,
      'Your team started ' || ws.started || ' "' || ws.wf || '" workflow'
        || CASE WHEN ws.started>1 THEN 's' ELSE '' END
        || ' but only completed ' || ws.completed || ' ('
        || ROUND((ws.completed::NUMERIC / ws.started * 100)::numeric,0)
        || '%). Reviewing where they stall can recover this effort.',
      jsonb_build_object('workflow', ws.wf, 'started', ws.started,
        'completed', ws.completed,
        'abandonment_pct', ROUND(((1 - ws.completed::NUMERIC / ws.started) * 100)::numeric,1)),
      0.65,
      jsonb_build_object('description', 'Recovered workflow effort')
    FROM wf_stats ws
    WHERE ws.started >= 3 AND ws.completed::NUMERIC / ws.started < 0.5
      AND NOT has_open_recommendation(p_business_id, 'USAGE-002', NULL)
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    rule_id := 'USAGE-002'; issued_count := v_n; RETURN NEXT;
  EXCEPTION WHEN OTHERS THEN
    rule_id := 'USAGE-002'; issued_count := 0; RETURN NEXT;
  END;

  -- SECTOR-001 (#16/#17): A module popular in your sector that you haven't enabled.
  -- "80% of businesses in your sector use [module], but you haven't enabled it."
  -- §21 guard: sector sample >= 5 businesses (small sectors suppressed — honest).
  BEGIN
    WITH my_industry AS (
      SELECT COALESCE(b.industry, 'unspecified') AS ind
      FROM businesses b WHERE b.id = p_business_id
    ),
    sector_selected AS (
      SELECT unnest(COALESCE(uws.selected_tools, '{}'::TEXT[])) AS module_key
      FROM user_workspace_selections uws
      JOIN businesses b ON b.id = uws.business_id
      JOIN my_industry mi ON COALESCE(b.industry, 'unspecified') = mi.ind
    ),
    sector_total AS (
      SELECT COUNT(DISTINCT uws.business_id) AS n
      FROM user_workspace_selections uws
      JOIN businesses b ON b.id = uws.business_id
      JOIN my_industry mi ON COALESCE(b.industry, 'unspecified') = mi.ind
    ),
    my_selected AS (
      SELECT unnest(COALESCE(uws.selected_tools, '{}'::TEXT[])) AS module_key
      FROM user_workspace_selections uws WHERE uws.business_id = p_business_id
    ),
    sector_agg AS (
      SELECT module_key, COUNT(*) AS sector_count
      FROM sector_selected GROUP BY module_key
    )
    INSERT INTO claims (business_id, claim_type, status, rule_id, severity,
      subject_type, subject_id, statement, evidence, confidence, expected_impact)
    SELECT p_business_id, 'RECOMMENDATION', 'issued', 'SECTOR-001', 'info',
      'module', NULL,
      ROUND((sa.sector_count::NUMERIC / (SELECT n FROM sector_total) * 100)::numeric,0)
        || '% of businesses in your sector ("' || (SELECT ind FROM my_industry)
        || '") use "' || sa.module_key || '", but you haven''t enabled it. Consider
        whether it''s relevant to your operations.',
      jsonb_build_object('module_key', sa.module_key,
        'sector_businesses_selected', sa.sector_count,
        'sector_sample_size', (SELECT n FROM sector_total),
        'sector_adoption_pct', ROUND((sa.sector_count::NUMERIC / (SELECT n FROM sector_total) * 100)::numeric,1)),
      0.5,
      jsonb_build_object('description', 'Catch up to sector norms')
    FROM sector_agg sa
    WHERE (SELECT n FROM sector_total) >= 5  -- §21 small-data guard
      AND sa.sector_count::NUMERIC / (SELECT n FROM sector_total) >= 0.5
      AND NOT EXISTS (SELECT 1 FROM my_selected ms WHERE ms.module_key = sa.module_key)
      AND NOT has_open_recommendation(p_business_id, 'SECTOR-001', NULL)
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    rule_id := 'SECTOR-001'; issued_count := v_n; RETURN NEXT;
  EXCEPTION WHEN OTHERS THEN
    rule_id := 'SECTOR-001'; issued_count := 0; RETURN NEXT;
  END;

  RETURN;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.run_business_health_audit(p_business_id UUID)
RETURNS INTEGER
AS $guard$

DECLARE
  v_count INTEGER := 0;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  INSERT INTO self_audit_findings (business_id, audit_dimension, category, severity, title, detail, entity_type, entity_id)
  SELECT p_business_id, 'business_health', 'incomplete_record', 'warning',
    'Invoice without a contact', 'Invoice has no contact linked',
    'invoice', i.id
  FROM invoices i WHERE i.business_id = p_business_id AND i.contact_id IS NULL
  ON CONFLICT DO NOTHING;

  INSERT INTO self_audit_findings (business_id, audit_dimension, category, severity, title, detail, entity_type, entity_id)
  SELECT p_business_id, 'business_health', 'financial_anomaly', 'critical',
    'Overdue invoice', CONCAT('Invoice overdue, total ', i.total),
    'invoice', i.id
  FROM invoices i WHERE i.business_id = p_business_id AND i.status = 'overdue'
  ON CONFLICT DO NOTHING;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.run_recommendation_rules(p_business_id UUID)
RETURNS TABLE(rule_id TEXT, issued_count INTEGER)
AS $guard$

DECLARE
  v_n INTEGER;
  v_today DATE := CURRENT_DATE;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN;
  END IF;

  -- FIN-AR-001: Receivables concentration — top customer > 40% of overdue.
  -- §21 guard: needs >= 5 overdue invoices.
  BEGIN
    WITH overdue AS (
      SELECT COALESCE(NULLIF(client_name,''),'Unknown') AS cust, SUM(total) AS amt, COUNT(*) AS n
      FROM invoices
      WHERE business_id = p_business_id AND lower(status)='overdue'
      GROUP BY COALESCE(NULLIF(client_name,''),'Unknown')
    ),
    totals AS (
      SELECT SUM(amt) AS total_amt, SUM(n) AS total_n FROM overdue
    )
    INSERT INTO claims (business_id, claim_type, status, rule_id, severity,
      subject_type, subject_id, statement, evidence, confidence, expected_impact)
    SELECT p_business_id, 'RECOMMENDATION', 'issued', 'FIN-AR-001', 'critical',
      'customer', NULL,
      o.cust || ' represents ' || round((o.amt / t.total_amt * 100)::numeric,0)
        || '% of your overdue receivables (' || to_char(o.amt, 'FM999,999,999')
        || ' across ' || o.n || ' invoice' || CASE WHEN o.n>1 THEN 's' ELSE '' END
        || '). Concentrating collection effort here has the highest recovery potential.',
      jsonb_build_object(
        'customer', o.cust,
        'overdue_amount', o.amt,
        'overdue_invoice_count', o.n,
        'total_overdue', t.total_amt,
        'concentration_pct', round((o.amt / t.total_amt * 100)::numeric,1),
        'period', 'point_in_time'),
      0.8,
      jsonb_build_object('amount', o.amt, 'description', 'Potential recovery if collected', 'metric_key', 'overdue_receivables')
    FROM overdue o, totals t
    WHERE t.total_n >= 5
      AND o.amt / t.total_amt > 0.40
      AND NOT has_open_recommendation(p_business_id, 'FIN-AR-001', NULL)
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    rule_id := 'FIN-AR-001'; issued_count := v_n; RETURN NEXT;
  EXCEPTION WHEN OTHERS THEN
    rule_id := 'FIN-AR-001'; issued_count := 0; RETURN NEXT;
  END;

  -- FIN-AR-002: Per-customer overdue aging — customers with invoices overdue
  -- by > 30 days. §21 guard: at least 1 overdue invoice.
  BEGIN
    INSERT INTO claims (business_id, claim_type, status, rule_id, severity,
      subject_type, subject_id, statement, evidence, confidence, expected_impact)
    SELECT p_business_id, 'RECOMMENDATION', 'issued', 'FIN-AR-002', 'warning',
      'customer', NULL,
      COALESCE(NULLIF(i.client_name,''),'A customer') || ' has '
        || COUNT(*) || ' invoice(s) overdue by more than 30 days totalling '
        || to_char(SUM(i.total), 'FM999,999,999')
        || '. The longer receivables age, the lower the recovery probability.',
      jsonb_build_object(
        'customer', COALESCE(NULLIF(i.client_name,''),'Unknown'),
        'overdue_invoice_count', COUNT(*),
        'overdue_amount', SUM(i.total),
        'oldest_due_date', MIN(i.due_date),
        'period', 'point_in_time'),
      0.85,
      jsonb_build_object('amount', SUM(i.total), 'description', 'Recoverable if collected promptly', 'metric_key', 'overdue_receivables')
    FROM invoices i
    WHERE i.business_id = p_business_id
      AND lower(i.status)='overdue'
      AND i.due_date IS NOT NULL
      AND i.due_date < v_today - 30
    GROUP BY COALESCE(NULLIF(i.client_name,''),'Unknown')
    HAVING NOT has_open_recommendation(p_business_id, 'FIN-AR-002', NULL)
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    rule_id := 'FIN-AR-002'; issued_count := v_n; RETURN NEXT;
  EXCEPTION WHEN OTHERS THEN
    rule_id := 'FIN-AR-002'; issued_count := 0; RETURN NEXT;
  END;

  -- FIN-CF-001: Cash-flow negative trend — expenses > revenue over 90d.
  -- §21 guard: needs >= 14 days of cashflow history.
  BEGIN
    WITH cf AS (
      SELECT
        COALESCE(SUM(CASE WHEN type='income' THEN amount ELSE 0 END),0) AS inc,
        COALESCE(SUM(CASE WHEN type='expense' THEN amount ELSE 0 END),0) AS exp,
        COUNT(DISTINCT date) AS days
      FROM cashflow_entries
      WHERE business_id = p_business_id AND date >= v_today - 90
    )
    INSERT INTO claims (business_id, claim_type, status, rule_id, severity,
      subject_type, subject_id, statement, evidence, confidence, expected_impact)
    SELECT p_business_id, 'RECOMMENDATION', 'issued', 'FIN-CF-001', 'critical',
      'business', NULL,
      'Over the last 90 days, expenses (' || to_char(cf.exp,'FM999,999,999')
        || ') exceeded income (' || to_char(cf.inc,'FM999,999,999')
        || '), a net cash outflow of ' || to_char((cf.exp - cf.inc),'FM999,999,999')
        || '. Sustained outflows erode cash reserves; review major expense categories.',
      jsonb_build_object(
        'income_90d', cf.inc, 'expense_90d', cf.exp,
        'net_90d', cf.inc - cf.exp, 'days_of_history', cf.days,
        'period', 'trailing_90d'),
      0.8,
      jsonb_build_object('amount', cf.exp - cf.inc, 'description', 'Cash burn to arrest', 'metric_key', 'revenue_collected')
    FROM cf
    WHERE cf.days >= 14 AND cf.exp > cf.inc
      AND NOT has_open_recommendation(p_business_id, 'FIN-CF-001', NULL)
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    rule_id := 'FIN-CF-001'; issued_count := v_n; RETURN NEXT;
  EXCEPTION WHEN OTHERS THEN
    rule_id := 'FIN-CF-001'; issued_count := 0; RETURN NEXT;
  END;

  -- SAL-CONV-001: Sales pipeline stagnation — deals stuck in the same stage
  -- > 21 days. §21 guard: needs >= 1 open deal.
  BEGIN
    INSERT INTO claims (business_id, claim_type, status, rule_id, severity,
      subject_type, subject_id, statement, evidence, confidence, expected_impact)
    SELECT p_business_id, 'RECOMMENDATION', 'issued', 'SAL-CONV-001', 'warning',
      'deal', d.id,
      'Deal "' || d.title || '" has been in the ' || d.stage
        || ' stage for ' || extract(day from now() - d.updated_at)
        || ' days. Deals that stagnate rarely close; a follow-up may recover '
        || to_char(d.value, 'FM999,999,999') || ' in pipeline value.',
      jsonb_build_object(
        'deal_id', d.id, 'deal_title', d.title, 'stage', d.stage,
        'value', d.value, 'days_in_stage', extract(day from now() - d.updated_at),
        'owner_id', d.owner_id, 'period', 'point_in_time'),
      0.7,
      jsonb_build_object('amount', d.value, 'description', 'Pipeline value at risk', 'metric_key', 'pipeline_value')
    FROM deals d
    WHERE d.business_id = p_business_id
      AND lower(d.stage) NOT IN ('won','lost','closed_won','closed-won','closed-lost')
      AND d.updated_at < now() - interval '21 days'
      AND NOT has_open_recommendation(p_business_id, 'SAL-CONV-001', d.id)
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    rule_id := 'SAL-CONV-001'; issued_count := v_n; RETURN NEXT;
  EXCEPTION WHEN OTHERS THEN
    rule_id := 'SAL-CONV-001'; issued_count := 0; RETURN NEXT;
  END;

  -- INV-001: Low-stock reorder — products at/below reorder threshold.
  BEGIN
    INSERT INTO claims (business_id, claim_type, status, rule_id, severity,
      subject_type, subject_id, statement, evidence, confidence, expected_impact)
    SELECT p_business_id, 'RECOMMENDATION', 'issued', 'INV-001', 'warning',
      'product', p.id,
      'Stock for "' || p.name || '" is at ' || p.stock || ' units (reorder level '
        || COALESCE(p.low_stock_threshold,0) || '). A stock-out would interrupt sales of this item.',
      jsonb_build_object(
        'product_id', p.id, 'product_name', p.name, 'sku', p.sku,
        'current_stock', p.stock, 'reorder_level', p.low_stock_threshold,
        'unit_cost', p.cost, 'period', 'point_in_time'),
      0.9,
      jsonb_build_object('description', 'Avoid stock-out; create a purchase order', 'metric_key', 'inventory_low_count')
    FROM products p
    WHERE p.business_id = p_business_id
      AND p.stock <= COALESCE(p.low_stock_threshold, 0)
      AND NOT has_open_recommendation(p_business_id, 'INV-001', p.id)
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    rule_id := 'INV-001'; issued_count := v_n; RETURN NEXT;
  EXCEPTION WHEN OTHERS THEN
    rule_id := 'INV-001'; issued_count := 0; RETURN NEXT;
  END;

  -- CUST-001: Customer inactivity — customers with no invoice in > 90 days who
  -- previously had invoices. §21 guard: customer must have >= 2 historical
  -- invoices (so "inactivity" is meaningful, not a one-off buyer).
  BEGIN
    INSERT INTO claims (business_id, claim_type, status, rule_id, severity,
      subject_type, subject_id, statement, evidence, confidence, expected_impact)
    SELECT p_business_id, 'RECOMMENDATION', 'issued', 'CUST-001', 'info',
      'customer', c.id,
      COALESCE(c.name,'A customer') || ' has not been invoiced in '
        || extract(day from now() - last_inv.last_at) || ' days, though they had '
        || last_inv.n || ' prior invoice(s) totalling '
        || to_char(last_inv.total, 'FM999,999,999')
        || '. A check-in may recover a recurring relationship.',
      jsonb_build_object(
        'customer_id', c.id, 'customer_name', c.name,
        'last_invoice_at', last_inv.last_at,
        'prior_invoice_count', last_inv.n,
        'prior_invoice_total', last_inv.total,
        'inactive_days', extract(day from now() - last_inv.last_at),
        'period', 'point_in_time'),
      0.6,
      jsonb_build_object('description', 'Potential repeat business recovery', 'metric_key', 'customer_count')
    FROM contacts c
    JOIN LATERAL (
      SELECT MAX(inv.created_at) AS last_at, COUNT(*) AS n, SUM(inv.total) AS total
      FROM invoices inv
      WHERE inv.business_id = p_business_id
        AND COALESCE(NULLIF(inv.client_name,''), inv.client_email) = COALESCE(NULLIF(c.name,''), c.email)
    ) last_inv ON true
    WHERE c.business_id = p_business_id
      AND c.name IS NOT NULL AND c.name <> ''
      AND last_inv.n >= 2
      AND last_inv.last_at < now() - interval '90 days'
      AND NOT has_open_recommendation(p_business_id, 'CUST-001', c.id)
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    rule_id := 'CUST-001'; issued_count := v_n; RETURN NEXT;
  EXCEPTION WHEN OTHERS THEN
    rule_id := 'CUST-001'; issued_count := 0; RETURN NEXT;
  END;

  -- OPS-001: Task overload — a staff member with > 8 open tasks.
  -- §21 guard: staff must have >= 8 open tasks (meaningful overload).
  BEGIN
    INSERT INTO claims (business_id, claim_type, status, rule_id, severity,
      subject_type, subject_id, statement, evidence, confidence, expected_impact)
    SELECT p_business_id, 'RECOMMENDATION', 'issued', 'OPS-001', 'warning',
      'staff', s.id,
      COALESCE(s.name, s.full_name, 'A team member') || ' has ' || open_cnt.n
        || ' open tasks, which is above the typical workload. Reassigning or '
        || 'reprioritising may reduce the risk of overdue work.',
      jsonb_build_object(
        'staff_id', s.id, 'open_task_count', open_cnt.n,
        'overdue_count', open_cnt.overdue,
        'period', 'point_in_time'),
      0.65,
      jsonb_build_object('description', 'Reduce overload risk', 'metric_key', 'task_overdue_count')
    FROM staff s
    JOIN LATERAL (
      SELECT COUNT(*) AS n,
        COUNT(*) FILTER (WHERE t.due_date IS NOT NULL AND t.due_date < v_today) AS overdue
      FROM tasks t
      WHERE t.business_id = p_business_id
        AND t.assignee_id = s.id
        AND lower(t.status) NOT IN ('done','completed','cancelled','canceled')
    ) open_cnt ON true
    WHERE s.business_id = p_business_id
      AND open_cnt.n >= 8
      AND NOT has_open_recommendation(p_business_id, 'OPS-001', s.id)
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    rule_id := 'OPS-001'; issued_count := v_n; RETURN NEXT;
  EXCEPTION WHEN OTHERS THEN
    rule_id := 'OPS-001'; issued_count := 0; RETURN NEXT;
  END;

  -- DQ-001: Data-quality blocking intelligence — if scan_data_quality found
  -- critical issues, recommend running the data-quality review. Refers to the
  -- findings written by 089. §21 guard: >= 1 critical finding.
  BEGIN
    INSERT INTO claims (business_id, claim_type, status, rule_id, severity,
      subject_type, subject_id, statement, evidence, confidence, expected_impact)
    SELECT p_business_id, 'RECOMMENDATION', 'issued', 'DQ-001', 'warning',
      'business', NULL,
      dq.cnt || ' critical data-quality issue(s) were found (e.g. negative '
        || 'invoice totals, unreconciled payments). These can corrupt '
        || 'metrics and intelligence; reviewing them improves every number '
        || 'Avenize shows you.',
      jsonb_build_object(
        'critical_count', dq.cnt,
        'total_findings', dq.total,
        'period', 'point_in_time'),
      0.9,
      jsonb_build_object('description', 'Improve metric reliability', 'metric_key', 'data_quality_score')
    FROM (
      SELECT COUNT(*) FILTER (WHERE severity='critical') AS cnt,
             COUNT(*) AS total
      FROM self_audit_findings
      WHERE business_id = p_business_id AND audit_dimension='data_quality' AND resolved=false
    ) dq
    WHERE dq.cnt >= 1
      AND NOT has_open_recommendation(p_business_id, 'DQ-001', NULL)
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    rule_id := 'DQ-001'; issued_count := v_n; RETURN NEXT;
  EXCEPTION WHEN OTHERS THEN
    rule_id := 'DQ-001'; issued_count := 0; RETURN NEXT;
  END;

  RETURN;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.run_reconciliation(p_business_id UUID, p_check_name TEXT)
RETURNS JSONB
AS $guard$

DECLARE
  v_result JSONB;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  IF p_check_name = 'sales_finance_invoice_totals' THEN
    -- Sales (deals) vs Finance (invoices): compare deal value to invoice total.
    INSERT INTO reconciliation_runs (business_id, source_domain, target_domain, check_name, status, detail)
    SELECT p_business_id, 'sales', 'finance', p_check_name,
      CASE WHEN COALESCE(sum(d.value),0) = COALESCE(sum(i.total) FILTER (WHERE i.status='paid'),0)
        THEN 'reconciled' ELSE 'discrepancy' END,
      jsonb_build_object('deal_total', sum(d.value), 'invoice_paid_total', sum(i.total) FILTER (WHERE i.status='paid'))
    FROM deals d LEFT JOIN invoices i ON i.business_id = d.business_id
    WHERE d.business_id = p_business_id;
  ELSIF p_check_name = 'inventory_accounting_stock_value' THEN
    INSERT INTO reconciliation_runs (business_id, source_domain, target_domain, check_name, status, detail)
    VALUES (p_business_id, 'inventory', 'accounting', p_check_name, 'unreconciled',
      jsonb_build_object('note', 'GL stock account not yet wired'));
  ELSE
    INSERT INTO reconciliation_runs (business_id, source_domain, target_domain, check_name, status, detail)
    VALUES (p_business_id, 'unknown', 'unknown', p_check_name, 'unreconciled',
      jsonb_build_object('note', 'Unknown reconciliation check'));
  END IF;

  SELECT jsonb_build_object('check', p_check_name, 'status', 'executed') INTO v_result;
  RETURN v_result;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.run_simulation(p_business_id UUID, p_scenario TEXT, p_inputs JSONB)
RETURNS JSONB
AS $guard$

DECLARE
  v_out JSONB; v_raise_pct NUMERIC; v_staff_id UUID;
  v_current_salary NUMERIC; v_new_monthly NUMERIC; v_old_monthly NUMERIC;
  v_annual_impact NUMERIC; v_count INTEGER; v_avg_salary NUMERIC;
  v_revenue NUMERIC; v_expenses NUMERIC; v_cash NUMERIC;
  v_payroll_monthly NUMERIC; v_coverage_months NUMERIC; v_margin NUMERIC;
  v_new_payroll NUMERIC; v_new_coverage NUMERIC; v_new_margin NUMERIC;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  -- Pull real financial context.
  SELECT COALESCE(sum(CASE WHEN status='paid' THEN total END),0)
  INTO v_revenue FROM invoices WHERE business_id = p_business_id;
  v_expenses := COALESCE(v_revenue * 0.6, 0); -- proxy until expenses table aggregates
  v_cash := v_revenue - v_expenses;

  -- Current monthly payroll.
  SELECT COALESCE(sum(base_salary),0) / 12.0,
         count(*)
  INTO v_payroll_monthly, v_count
  FROM staff WHERE business_id = p_business_id;

  IF p_scenario = 'salary_increase' THEN
    v_raise_pct := (p_inputs ->> 'raise_pct')::NUMERIC / 100.0;
    v_staff_id := NULLIF(p_inputs ->> 'staff_id','')::UUID;
    IF v_staff_id IS NOT NULL THEN
      SELECT base_salary INTO v_current_salary FROM staff WHERE id = v_staff_id;
      v_old_monthly := COALESCE(v_current_salary,0) / 12.0;
      v_new_monthly := v_old_monthly * (1 + v_raise_pct);
      v_annual_impact := (v_new_monthly - v_old_monthly) * 12;
      v_new_payroll := v_payroll_monthly + (v_new_monthly - v_old_monthly);
    ELSE
      v_annual_impact := v_payroll_monthly * v_raise_pct * 12;
      v_new_payroll := v_payroll_monthly * (1 + v_raise_pct);
    END IF;
    v_new_coverage := CASE WHEN v_new_payroll = 0 THEN 999
      ELSE (v_cash / v_new_payroll) END;
    v_margin := CASE WHEN v_revenue = 0 THEN 0 ELSE (v_revenue - v_expenses) / v_revenue END;
    v_new_margin := CASE WHEN v_revenue = 0 THEN 0
      ELSE (v_revenue - v_expenses - (v_annual_impact/12)) / v_revenue END;

    v_out := jsonb_build_object(
      'monthly_payroll_impact', jsonb_build_object(
        'value', v_new_payroll - v_payroll_monthly,
        'assumption', 'single increase applied to current monthly payroll',
        'range_low', (v_new_payroll - v_payroll_monthly) * 0.95,
        'range_high', (v_new_payroll - v_payroll_monthly) * 1.05,
        'type', 'ESTIMATE'),
      'annual_impact', jsonb_build_object(
        'value', v_annual_impact, 'assumption', '12x monthly delta',
        'range_low', v_annual_impact * 0.95, 'range_high', v_annual_impact * 1.05,
        'type', 'ESTIMATE'),
      'cash_coverage_months', jsonb_build_object(
        'value', round(v_new_coverage::numeric, 1),
        'assumption', 'current cash / new monthly payroll, no revenue growth assumed',
        'type', 'ESTIMATE'),
      'margin_after', jsonb_build_object(
        'value', round((v_new_margin*100)::numeric, 1),
        'assumption', 'margin with annualized increase subtracted monthly',
        'type', 'ESTIMATE'),
      'employees_affected', jsonb_build_object('value', CASE WHEN v_staff_id IS NOT NULL THEN 1 ELSE v_count END, 'type','FACT'),
      'alternatives', jsonb_build_array(
        jsonb_build_object('label','Smaller increase', 'raise_pct', greatest(v_raise_pct*50, 0.02)),
        jsonb_build_object('label','Performance-bonus instead', 'note','One-off, no recurring payroll impact'),
        jsonb_build_object('label','Defer to next cycle', 'note','Preserves current cash coverage')
      )
    );

  ELSIF p_scenario = 'mass_hire' THEN
    v_count := (p_inputs ->> 'count')::INTEGER;
    v_avg_salary := COALESCE((p_inputs ->> 'avg_salary')::NUMERIC,
      CASE WHEN (SELECT count(*) FROM staff WHERE business_id=p_business_id) > 0
        THEN (SELECT avg(base_salary) FROM staff WHERE business_id=p_business_id)
        ELSE 50000 END);
    v_new_monthly := (v_count * v_avg_salary) / 12.0;
    v_new_payroll := v_payroll_monthly + v_new_monthly;
    v_new_coverage := CASE WHEN v_new_payroll = 0 THEN 999 ELSE v_cash / v_new_payroll END;
    v_out := jsonb_build_object(
      'monthly_payroll_impact', jsonb_build_object('value', v_new_monthly, 'type','ESTIMATE',
        'assumption','count x average salary / 12'),
      'annual_impact', jsonb_build_object('value', v_new_monthly*12, 'type','ESTIMATE'),
      'cash_coverage_months', jsonb_build_object('value', round(v_new_coverage::numeric,1), 'type','ESTIMATE',
        'assumption','cash / new payroll'),
      'employees_affected', jsonb_build_object('value', v_count, 'type','FACT'),
      'alternatives', jsonb_build_array(
        jsonb_build_object('label','Hire fewer', 'count', greatest(v_count-1,1)),
        jsonb_build_object('label','Outsource', 'note','Variable cost, no fixed payroll'),
        jsonb_build_object('label','Reprioritize existing capacity', 'note','No new headcount')
      )
    );

  ELSIF p_scenario = 'revenue_change' THEN
    v_count := (p_inputs ->> 'delta_pct')::INTEGER;
    v_new_payroll := v_payroll_monthly;
    v_new_coverage := CASE WHEN v_new_payroll = 0 THEN 999 ELSE ((v_cash * (1 + v_count/100.0)) / v_new_payroll) END;
    v_out := jsonb_build_object(
      'cash_impact', jsonb_build_object('value', round((v_cash * v_count/100.0)::numeric,0), 'type','ESTIMATE',
        'assumption','linear revenue change applied to current cash'),
      'payroll_coverage_months', jsonb_build_object('value', round(v_new_coverage::numeric,1), 'type','ESTIMATE'),
      'assumptions', jsonb_build_array('expenses held constant','no collection delay modeled'),
      'alternatives', jsonb_build_array(
        jsonb_build_object('label','Cut discretionary spend','note','Protects runway'),
        jsonb_build_object('label','Delay hiring','note','Preserves cash')
      )
    );

  ELSE
    v_out := jsonb_build_object('note','Custom scenario — provide assumptions manually', 'type','ESTIMATE');
  END IF;

  RETURN v_out;
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.run_system_health_audit(p_business_id UUID)
RETURNS INTEGER
AS $guard$

DECLARE
  v_count INTEGER := 0;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  INSERT INTO self_audit_findings (business_id, audit_dimension, category, severity, title, detail, entity_type, entity_id)
  SELECT p_business_id, 'system_health', 'stale_data', 'warning',
    'Stale entity: ' || entity_type, 'No events for ' || entity_type || ' in 30 days',
    entity_type, entity_id
  FROM entity_freshness
  WHERE business_id = p_business_id AND freshness_tier IN ('stale','old')
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_count = ROW_COUNT;

  INSERT INTO self_audit_findings (business_id, audit_dimension, category, severity, title, detail, entity_type, entity_id)
  SELECT p_business_id, 'system_health', 'missing_audit_event', 'warning',
    'Work route with no audit event', CONCAT('Route ', wr.id, ' has no matching business event'),
    'work_route', wr.id
  FROM work_routes wr
  WHERE wr.business_id = p_business_id AND NOT EXISTS (
    SELECT 1 FROM business_events e
    WHERE e.business_id = p_business_id AND e.entity_type = 'work_route' AND e.entity_id = wr.id
  )
  ON CONFLICT DO NOTHING;

  RETURN v_count;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.salary_affordability(p_business_id UUID)
RETURNS JSONB
AS $guard$

DECLARE
  v_payroll_monthly NUMERIC; v_cash NUMERIC; v_receivables NUMERIC;
  v_coverage NUMERIC; v_risk TEXT;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(sum(base_salary),0)/12.0 INTO v_payroll_monthly
  FROM staff WHERE business_id = p_business_id;
  SELECT COALESCE(sum(CASE WHEN status='paid' THEN total END),0) -
         COALESCE(sum(CASE WHEN status='paid' THEN total END),0)*0.6
  INTO v_cash FROM invoices WHERE business_id = p_business_id;
  SELECT COALESCE(sum(CASE WHEN status IN ('sent','overdue') THEN total END),0)
  INTO v_receivables FROM invoices WHERE business_id = p_business_id;
  v_coverage := CASE WHEN v_payroll_monthly = 0 THEN 999 ELSE v_cash / v_payroll_monthly END;
  v_risk := CASE WHEN v_coverage < 1 THEN 'critical' WHEN v_coverage < 3 THEN 'warning' ELSE 'ok' END;

  RETURN jsonb_build_object(
    'monthly_payroll', v_payroll_monthly,
    'available_cash', v_cash,
    'incoming_receivables', v_receivables,
    'payroll_coverage_months', round(v_coverage::numeric, 1),
    'risk_tier', v_risk,
    'scenarios', jsonb_build_array(
      jsonb_build_object('label','Across-the-board 10% increase','monthly_impact', v_payroll_monthly*0.10, 'coverage_after', CASE WHEN v_payroll_monthly=0 THEN 999 ELSE v_cash/(v_payroll_monthly*1.1) END),
      jsonb_build_object('label','Targeted top-performer increase','monthly_impact', v_payroll_monthly*0.03, 'coverage_after', CASE WHEN v_payroll_monthly=0 THEN 999 ELSE v_cash/(v_payroll_monthly*1.03) END),
      jsonb_build_object('label','Collection intervention first','note','Accelerate receivables to fund increases', 'coverage_after', CASE WHEN v_payroll_monthly=0 THEN 999 ELSE (v_cash+v_receivables*0.5)/v_payroll_monthly END)
    ),
    'type','ESTIMATE',
    'assumptions','cash proxies revenue minus 60% expenses; coverage assumes no revenue growth'
  );
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.sales_index(p_business_id UUID)
RETURNS JSONB
AS $guard$

DECLARE
  v_paid NUMERIC; v_overdue NUMERIC; v_total NUMERIC; v_count INTEGER;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(sum(CASE WHEN status='paid' THEN total END),0),
         COALESCE(sum(CASE WHEN status='overdue' THEN total END),0),
         COALESCE(sum(total),0), count(*)
  INTO v_paid, v_overdue, v_total, v_count
  FROM invoices WHERE business_id = p_business_id;
  RETURN jsonb_build_object(
    'signals', jsonb_build_object(
      'revenue_collected', v_paid,
      'overdue', v_overdue,
      'total_billed', v_total,
      'invoice_count', v_count
    ),
    'score', CASE WHEN v_total = 0 THEN 0 ELSE LEAST(100, ((v_paid / NULLIF(v_total,0)) * 100)::INTEGER) END,
    'components', jsonb_build_array('revenue_collected','overdue','collection_rate')
  );
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.sales_performance_intelligence(p_business_id UUID)
RETURNS JSONB
AS $guard$

DECLARE
  v_rows JSONB;
  v_count INTEGER := 0;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'staff_id', st.staff_id,
    'target_amount', st.revenue_target,
    'achieved_amount', COALESCE(won.achieved, 0),
    'attainment_pct', CASE WHEN st.revenue_target > 0
      THEN round((COALESCE(won.achieved, 0) / st.revenue_target * 100)::numeric, 1)
      ELSE 0 END,
    'status', CASE
      WHEN st.revenue_target > 0 AND COALESCE(won.achieved, 0) >= st.revenue_target THEN 'on_track'
      WHEN st.revenue_target > 0 AND COALESCE(won.achieved, 0) >= st.revenue_target * 0.5 THEN 'at_risk'
      WHEN st.revenue_target > 0 THEN 'behind'
      ELSE 'no_target'
    END
  ) ORDER BY st.period_start DESC), '[]'::JSONB)
  INTO v_rows
  FROM sales_targets st
  LEFT JOIN LATERAL (
    SELECT SUM(d.value) AS achieved
    FROM deals d
    WHERE d.assigned_to = st.staff_id
      AND d.business_id = p_business_id
      AND lower(d.stage) IN ('won','closed_won','closed-won')
  ) won ON true
  WHERE st.business_id = p_business_id
    AND st.status = 'active';

  SELECT jsonb_array_length(v_rows) INTO v_count;

  RETURN jsonb_build_object(
    'targets', v_rows,
    'target_count', v_count,
    'type', CASE WHEN v_count = 0 THEN 'FACT' ELSE 'INFERENCE' END,
    'note', CASE WHEN v_count = 0
      THEN 'No sales targets set yet. Set targets in Sales settings to see attainment.'
      ELSE 'Attainment compares closed-won deal value against active sales targets.' END
  );
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.scan_data_quality(p_business_id UUID)
RETURNS TABLE(category TEXT, found INTEGER)
AS $guard$

DECLARE
  v_n INTEGER;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN;
  END IF;

  -- 1. Orphaned invoice: no client name AND no deal link.
  BEGIN
    INSERT INTO self_audit_findings (business_id, audit_dimension, category, severity, title, detail, entity_type, entity_id, suggested_remediation)
    SELECT p_business_id, 'data_quality', 'orphaned_invoice', 'warning',
      'Invoice has no linked customer',
      'Invoice ' || COALESCE(invoice_number, left(id::TEXT,8)) || ' has no client name and no deal link, so customer exposure cannot be measured.',
      'invoice', id, 'Associate this invoice with a valid customer or deal.'
    FROM invoices
    WHERE business_id = p_business_id
      AND COALESCE(client_name,'') = ''
      AND deal_id IS NULL
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    category := 'orphaned_invoice'; found := v_n; RETURN NEXT;
  EXCEPTION WHEN OTHERS THEN NULL; END;

  -- 2. Missing due date on a sent/overdue invoice.
  BEGIN
    INSERT INTO self_audit_findings (business_id, audit_dimension, category, severity, title, detail, entity_type, entity_id, suggested_remediation)
    SELECT p_business_id, 'data_quality', 'missing_due_date', 'warning',
      'Invoice has no due date',
      'Invoice ' || COALESCE(invoice_number, left(id::TEXT,8)) || ' is ' || status || ' but has no due date; overdue tracking is unreliable.',
      'invoice', id, 'Set a due date so aging and reminders work.'
    FROM invoices
    WHERE business_id = p_business_id
      AND lower(status) IN ('sent','overdue') AND due_date IS NULL
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    category := 'missing_due_date'; found := v_n; RETURN NEXT;
  EXCEPTION WHEN OTHERS THEN NULL; END;

  -- 3. Negative / impossible money values.
  BEGIN
    INSERT INTO self_audit_findings (business_id, audit_dimension, category, severity, title, detail, entity_type, entity_id, suggested_remediation)
    SELECT p_business_id, 'data_quality', 'invalid_amount', 'critical',
      'Invoice total is negative',
      'Invoice ' || COALESCE(invoice_number, left(id::TEXT,8)) || ' has total ' || total || '. Negative invoiced amounts are impossible.',
      'invoice', id, 'Correct the invoice total.'
    FROM invoices
    WHERE business_id = p_business_id AND total < 0
    ON CONFLICT DO NOTHING;
    category := 'invalid_amount'; found := 0;
    GET DIAGNOSTICS v_n = ROW_COUNT; found := v_n; RETURN NEXT;
  EXCEPTION WHEN OTHERS THEN NULL; END;

  -- 4. Deal with no owner or non-positive value.
  BEGIN
    INSERT INTO self_audit_findings (business_id, audit_dimension, category, severity, title, detail, entity_type, entity_id, suggested_remediation)
    SELECT p_business_id, 'data_quality', 'incomplete_deal', 'warning',
      'Open deal has no owner',
      'Deal "' || title || '" (stage ' || COALESCE(stage,'?') || ') has no owner, so sales attribution cannot be computed.',
      'deal', id, 'Assign an owner to this deal.'
    FROM deals
    WHERE business_id = p_business_id AND owner_id IS NULL
      AND lower(stage) NOT IN ('won','lost','closed_won','closed-won','closed-lost')
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    category := 'incomplete_deal'; found := v_n; RETURN NEXT;
  EXCEPTION WHEN OTHERS THEN NULL; END;

  -- 5. Task missing assignee.
  BEGIN
    INSERT INTO self_audit_findings (business_id, audit_dimension, category, severity, title, detail, entity_type, entity_id, suggested_remediation)
    SELECT p_business_id, 'data_quality', 'unassigned_task', 'info',
      'Task has no assignee',
      'Task "' || title || '" has no assignee, so capacity and ownership intelligence cannot attribute it.',
      'task', id, 'Assign the task or close it.'
    FROM tasks
    WHERE business_id = p_business_id AND assignee_id IS NULL
      AND lower(status) NOT IN ('done','completed','cancelled','canceled')
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    category := 'unassigned_task'; found := v_n; RETURN NEXT;
  EXCEPTION WHEN OTHERS THEN NULL; END;

  -- 6. Stale entity: no business event touching it in >30 days. Uses the
  -- entity_freshness_status VIEW (freshness_tier is computed there, not on
  -- the base table) with a last_event_at fallback.
  BEGIN
    INSERT INTO self_audit_findings (business_id, audit_dimension, category, severity, title, detail, entity_type, entity_id, suggested_remediation)
    SELECT p_business_id, 'data_quality', 'stale_entity', 'info',
      INITCAP(entity_type) || ' has had no activity in 30+ days',
      'No business event has touched this ' || entity_type || ' recently. It may be abandoned or needing a follow-up.',
      entity_type, entity_id, 'Review whether this record is still relevant or needs a follow-up.'
    FROM entity_freshness_status
    WHERE business_id = p_business_id
      AND freshness_tier IN ('stale','old')
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    category := 'stale_entity'; found := v_n; RETURN NEXT;
  EXCEPTION WHEN OTHERS THEN NULL; END;

  -- 7. Duplicate contacts (same name within the business).
  BEGIN
    INSERT INTO self_audit_findings (business_id, audit_dimension, category, severity, title, detail, entity_type, entity_id, suggested_remediation)
    SELECT p_business_id, 'data_quality', 'duplicate_contact', 'warning',
      'Duplicate customer name',
      'Customer "' || name || '" appears ' || cnt || ' times. Duplicates split revenue and skew customer intelligence.',
      'contact', MIN(id),
      'Merge the duplicate contacts into one record.'
    FROM (
      SELECT name, MIN(id) AS id, COUNT(*) AS cnt
      FROM contacts WHERE business_id = p_business_id AND name IS NOT NULL AND name <> ''
      GROUP BY name HAVING COUNT(*) > 1
    ) d
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    category := 'duplicate_contact'; found := v_n; RETURN NEXT;
  EXCEPTION WHEN OTHERS THEN NULL; END;

  -- 8. Unreconciled payment: a successful payment with no linked invoice.
  BEGIN
    INSERT INTO self_audit_findings (business_id, audit_dimension, category, severity, title, detail, entity_type, entity_id, suggested_remediation)
    SELECT p_business_id, 'data_quality', 'unreconciled_payment', 'warning',
      'Successful payment not linked to an invoice',
      'Payment ' || COALESCE(reference, left(id::TEXT,8)) || ' of ' || amount || ' has no linked invoice; revenue attribution may be incomplete.',
      'payment', id, 'Link this payment to the correct invoice.'
    FROM payments
    WHERE business_id = p_business_id
      AND lower(status) IN ('successful','paid','completed','success')
      AND invoice_id IS NULL
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    category := 'unreconciled_payment'; found := v_n; RETURN NEXT;
  EXCEPTION WHEN OTHERS THEN NULL; END;

  -- Summary row into data_quality_checks (reconciliation view) — overall score.
  BEGIN
    INSERT INTO data_quality_checks (business_id, metric, sources, status, max_delta, resolution_hint)
    SELECT p_business_id, 'data_quality_scan',
      jsonb_build_object(
        'orphaned_invoices', (SELECT count(*) FROM self_audit_findings WHERE business_id = p_business_id AND audit_dimension='data_quality' AND category='orphaned_invoice'),
        'invalid_amounts', (SELECT count(*) FROM self_audit_findings WHERE business_id = p_business_id AND audit_dimension='data_quality' AND category='invalid_amount'),
        'unassigned_tasks', (SELECT count(*) FROM self_audit_findings WHERE business_id = p_business_id AND audit_dimension='data_quality' AND category='unassigned_task'),
        'duplicate_contacts', (SELECT count(*) FROM self_audit_findings WHERE business_id = p_business_id AND audit_dimension='data_quality' AND category='duplicate_contact')
      ),
      CASE WHEN EXISTS (
        SELECT 1 FROM self_audit_findings WHERE business_id = p_business_id AND audit_dimension='data_quality' AND severity='critical'
      ) THEN 'conflict' WHEN EXISTS (
        SELECT 1 FROM self_audit_findings WHERE business_id = p_business_id AND audit_dimension='data_quality'
      ) THEN 'stale' ELSE 'ok' END,
      NULL,
      'Run scan_data_quality periodically; resolve findings in the Data Quality view.'
    ON CONFLICT DO NOTHING;
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.scan_exceptions(p_business_id UUID)
RETURNS INTEGER
AS $guard$

DECLARE
  v_count INTEGER := 0; r RECORD;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  -- Overdue invoices
  FOR r IN SELECT id, total, due_date FROM invoices
    WHERE business_id = p_business_id AND status = 'overdue'
  LOOP
    INSERT INTO attention_exceptions (business_id, domain, severity, title, detail, entity_type, entity_id, suggested_action)
    VALUES (p_business_id, 'finance', 'critical',
      'Overdue invoice', CONCAT('Invoice overdue by ', CURRENT_DATE - r.due_date, ' days, ', r.total),
      'invoice', r.id, 'Follow up with the customer or send a reminder')
    ON CONFLICT DO NOTHING;
    v_count := v_count + 1;
  END LOOP;

  -- Low stock products
  FOR r IN SELECT id, name, stock, low_stock_threshold FROM products
    WHERE business_id = p_business_id AND stock <= COALESCE(low_stock_threshold,0)
  LOOP
    INSERT INTO attention_exceptions (business_id, domain, severity, title, detail, entity_type, entity_id, suggested_action)
    VALUES (p_business_id, 'inventory', 'warning',
      'Low stock', CONCAT(r.name, ' at ', r.stock, ' units (reorder at ', COALESCE(r.low_stock_threshold,0), ')'),
      'product', r.id, 'Create a purchase order to restock')
    ON CONFLICT DO NOTHING;
    v_count := v_count + 1;
  END LOOP;

  -- Overdue tasks
  FOR r IN SELECT id, title, due_date FROM tasks
    WHERE business_id = p_business_id AND status IN ('todo','in_progress') AND due_date < CURRENT_DATE
  LOOP
    INSERT INTO attention_exceptions (business_id, domain, severity, title, detail, entity_type, entity_id, suggested_action)
    VALUES (p_business_id, 'operations', 'warning',
      'Task overdue', CONCAT(r.title, ' was due ', r.due_date),
      'task', r.id, 'Reassign, re-baseline, or complete the task')
    ON CONFLICT DO NOTHING;
    v_count := v_count + 1;
  END LOOP;

  -- Unpaid payroll runs
  FOR r IN SELECT id, total_net, status FROM payroll_runs
    WHERE business_id = p_business_id AND status IN ('draft','calculated') AND total_net > 0
  LOOP
    INSERT INTO attention_exceptions (business_id, domain, severity, title, detail, entity_type, entity_id, suggested_action)
    VALUES (p_business_id, 'people', 'critical',
      'Payroll not paid', CONCAT('Payroll run ', r.status, ' totaling ', r.total_net, ' is not yet paid'),
      'payroll_run', r.id, 'Approve and fund payroll before the pay date')
    ON CONFLICT DO NOTHING;
    v_count := v_count + 1;
  END LOOP;

  -- Mark resolved: exceptions whose underlying record no longer matches.
  UPDATE attention_exceptions ae SET resolved = TRUE
  WHERE business_id = p_business_id AND resolved = FALSE
    AND NOT EXISTS (
      SELECT 1 FROM invoices i WHERE i.id = ae.entity_id AND i.status = 'overdue'
    ) AND ae.domain = 'finance';
  UPDATE attention_exceptions ae SET resolved = TRUE
  WHERE business_id = p_business_id AND resolved = FALSE
    AND NOT EXISTS (
      SELECT 1 FROM products p WHERE p.id = ae.entity_id AND p.stock <= COALESCE(p.low_stock_threshold,0)
    ) AND ae.domain = 'inventory';
  UPDATE attention_exceptions ae SET resolved = TRUE
  WHERE business_id = p_business_id AND resolved = FALSE
    AND NOT EXISTS (
      SELECT 1 FROM tasks t WHERE t.id = ae.entity_id AND t.status IN ('todo','in_progress') AND t.due_date < CURRENT_DATE
    ) AND ae.domain = 'operations';
  UPDATE attention_exceptions ae SET resolved = TRUE
  WHERE business_id = p_business_id AND resolved = FALSE
    AND NOT EXISTS (
      SELECT 1 FROM payroll_runs pr WHERE pr.id = ae.entity_id AND pr.status IN ('draft','calculated')
    ) AND ae.domain = 'people';

  RETURN v_count;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.similar_decisions(p_business_id UUID, p_query TEXT DEFAULT NULL, p_tags TEXT[] DEFAULT '{}')
RETURNS TABLE(id UUID, title TEXT, context TEXT, what_learned TEXT, learning_tags TEXT[], decided_at TIMESTAMPTZ)
AS $guard$

BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT id, title, context, what_learned, learning_tags, decided_at
  FROM decisions
  WHERE business_id = p_business_id AND status = 'reviewed'
    AND (
      (p_query IS NULL OR context ILIKE '%' || p_query || '%' OR title ILIKE '%' || p_query || '%')
      OR (p_tags <> '{}'::TEXT[] AND learning_tags && p_tags)
    )
  ORDER BY decided_at DESC LIMIT 10;
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.sla_breaches(p_business_id UUID)
RETURNS TABLE(entity_type TEXT, entity_id UUID, sla_status TEXT, age_hours NUMERIC, target_hours NUMERIC)
AS $guard$

BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT t.entity_type, t.entity_id, t.sla_status,
    round(extract(epoch from (now() - t.created_at))/3600, 1),
    d.target_complete_hours
  FROM sla_trackers t
  LEFT JOIN sla_definitions d ON d.business_id = t.business_id AND d.entity_type = t.entity_type AND d.is_active
  WHERE t.business_id = p_business_id AND t.sla_status IN ('warning','breached');
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.snapshot_config(p_business_id UUID, p_object_type TEXT, p_object_id UUID, p_snapshot JSONB)
RETURNS INTEGER
AS $guard$

DECLARE
  v_version INTEGER;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(max(version),0)+1 INTO v_version
  FROM configuration_versions
  WHERE business_id = p_business_id AND target_object_type = p_object_type AND target_object_id = p_object_id;
  INSERT INTO configuration_versions (business_id, target_object_type, target_object_id, version, snapshot, created_at)
  VALUES (p_business_id, p_object_type, p_object_id, v_version, p_snapshot, NOW());
  RETURN v_version;
END;

