CREATE OR REPLACE FUNCTION public.start_approval_protocol(p_business_id UUID, p_approval_id UUID, p_initiator_id UUID)
RETURNS UUID
AS $guard$

DECLARE
  v_run_id UUID;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  INSERT INTO action_protocol_runs (business_id, initiator_type, initiator_id,
    understanding, context, current_step, risk_level, created_at)
  VALUES (p_business_id, 'user', p_initiator_id,
    'Approval request', jsonb_build_object('approval_id', p_approval_id),
    'AUTHORIZE', 'medium', NOW())
  RETURNING id INTO v_run_id;

  -- Mark the early steps as done (the request already identified/understood/validated).
  PERFORM advance_action_step(v_run_id, 'IDENTIFY', 'Approval request identified');
  PERFORM advance_action_step(v_run_id, 'UNDERSTAND', 'Request details loaded');
  PERFORM advance_action_step(v_run_id, 'VALIDATE', 'Request validated against template');
  PERFORM advance_action_step(v_run_id, 'CONTEXTUALIZE', 'Context: authority + SoD checked');

  RETURN v_run_id;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.strategic_alignment(p_business_id UUID)
RETURNS JSONB
AS $guard$

DECLARE
  v_total INTEGER; v_underfunded INTEGER; v_list JSONB;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  SELECT count(*), count(*) FILTER (WHERE allocated_resources = '{}'::JSONB)
  INTO v_total, v_underfunded
  FROM strategic_objectives WHERE business_id = p_business_id AND level = 'objective' AND status='active';
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'title',title,'level',level,'has_resources', allocated_resources <> '{}'::JSONB)), '[]'::JSONB)
  INTO v_list FROM strategic_objectives WHERE business_id = p_business_id AND status='active' ORDER BY level, created_at;
  RETURN jsonb_build_object(
    'objectives_total', v_total,
    'underfunded', v_underfunded,
    'misalignment_detected', v_underfunded > 0,
    'note', CASE WHEN v_underfunded > 0
      THEN CONCAT(v_underfunded, ' active objective(s) have no allocated resources — possible strategic misalignment.')
      ELSE 'Active objectives appear resourced.' END,
    'objectives', v_list,
    'type','INFERENCE'
  );
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.sync_kr_from_metric(p_business_id UUID)
RETURNS INTEGER
AS $guard$

DECLARE v_n INTEGER := 0;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  UPDATE key_results kr
  SET current_value = km.current_value,
      updated_at = NOW()
  FROM kpi_metrics km
  WHERE kr.business_id = p_business_id
    AND kr.metric_key = km.metric_key
    AND km.business_id = p_business_id
    AND km.metric_key IS NOT NULL
    AND km.current_value IS NOT NULL
    -- Only the latest period per metric_key.
    AND km.period_end = (
      SELECT MAX(k2.period_end) FROM kpi_metrics k2
      WHERE k2.business_id = km.business_id AND k2.metric_key = km.metric_key
    );
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

