CREATE OR REPLACE FUNCTION public.trip_circuit_breaker(p_business_id UUID, p_agent_id UUID, p_anomaly TEXT, p_threshold JSONB DEFAULT NULL)
RETURNS UUID
AS $guard$

DECLARE
  v_id UUID; v_owner UUID;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  SELECT review_owner INTO v_owner FROM circuit_breaker_events
  WHERE business_id = p_business_id AND agent_id = p_agent_id AND reviewed = FALSE
  ORDER BY created_at DESC LIMIT 1;
  INSERT INTO circuit_breaker_events (business_id, agent_id, anomaly, threshold, action_taken, agent_frozen, review_owner, created_at)
  VALUES (p_business_id, p_agent_id, p_anomaly, p_threshold, 'frozen', TRUE, v_owner, NOW())
  RETURNING id INTO v_id;
  -- Freeze the agent so no further autonomous actions run until reviewed.
  UPDATE ai_agents SET is_active = FALSE WHERE id = p_agent_id;
  -- Surface as an attention exception so it appears in the Observer feed.
  INSERT INTO attention_exceptions (business_id, domain, severity, title, detail, entity_type, entity_id, suggested_action)
  VALUES (p_business_id, 'risk', 'critical',
    'AI agent circuit breaker tripped', p_anomaly,
    'ai_agent', p_agent_id, 'Review the agent action and unfreeze after confirming it is safe');
  RETURN v_id;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.trust_health(p_business_id UUID)
RETURNS JSONB
AS $guard$

DECLARE
  v_latest TIMESTAMPTZ;
  v_total_24h INTEGER;
  v_total_30d INTEGER;
  v_coverage JSONB;
  v_tables TEXT[] := ARRAY[
    'invoices','payments','journal_entries','staff','payroll_runs',
    'approvals','property_commissions','signature_requests','business_subscriptions',
    'claims','business_risks','key_results','kpi_metrics'
  ];
  v_t TEXT;
  v_recent_writes INTEGER;
  v_audit_rows INTEGER;
  v_gaps TEXT[] := '{}';
  v_covered TEXT[] := '{}';
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  -- Latest audit entry + volumes.
  SELECT max(created_at), count(*) FILTER (WHERE created_at > NOW() - INTERVAL '24 hours'),
         count(*) FILTER (WHERE created_at > NOW() - INTERVAL '30 days')
  INTO v_latest, v_total_24h, v_total_30d
  FROM audit_logs WHERE business_id = p_business_id;

  -- Per-table coverage: does the table have recent writes AND are those
  -- reflected in audit_logs? A table with writes but zero audit rows = the
  -- trigger may be broken (a trust gap). This is the integrity signal.
  FOREACH v_t IN ARRAY v_tables LOOP
    BEGIN
      EXECUTE format(
        'SELECT count(*) FROM %I WHERE business_id = $1 AND created_at > NOW() - INTERVAL ''7 days''',
        v_t
      ) INTO v_recent_writes USING p_business_id;

      SELECT count(*) INTO v_audit_rows FROM audit_logs
      WHERE business_id = p_business_id
        AND entity_type = v_t
        AND created_at > NOW() - INTERVAL '7 days';

      IF v_recent_writes > 0 THEN
        IF v_audit_rows = 0 THEN
          v_gaps := array_append(v_gaps, v_t);
        ELSE
          v_covered := array_append(v_covered, v_t);
        END IF;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      -- Table may not exist on this DB (migration not applied) — skip.
      NULL;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'latest_audit_at', v_latest,
    'audit_entries_24h', COALESCE(v_total_24h, 0),
    'audit_entries_30d', COALESCE(v_total_30d, 0),
    'audited_tables_with_recent_activity', v_covered,
    'audit_gaps', v_gaps,                          -- tables with writes but no audit rows
    'audit_healthy', array_length(v_gaps, 1) IS NULL OR array_length(v_gaps, 1) = 0,
    'checked_at', NOW()
  );
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.trust_index(p_business_id UUID)
RETURNS JSONB
AS $guard$

DECLARE
  v_fresh INTEGER; v_stale INTEGER; v_conflicts INTEGER; v_total INTEGER; v_score NUMERIC;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  SELECT count(*) FILTER (WHERE freshness_tier IN ('fresh','today')),
         count(*) FILTER (WHERE freshness_tier IN ('stale','old')),
         count(*)
  INTO v_fresh, v_stale, v_total
  FROM entity_freshness_status WHERE business_id = p_business_id;
  SELECT count(*) INTO v_conflicts FROM data_quality_checks
  WHERE business_id = p_business_id AND status = 'conflict';
  v_score := CASE WHEN v_total = 0 THEN 50 ELSE ((v_fresh::NUMERIC / v_total) * 100) - (v_conflicts * 10) END;
  RETURN jsonb_build_object(
    'signals', jsonb_build_object(
      'fresh_entities', v_fresh,
      'stale_entities', v_stale,
      'data_conflicts', v_conflicts,
      'freshness_ratio', CASE WHEN v_total = 0 THEN 0 ELSE (v_fresh::NUMERIC / v_total) END
    ),
    'score', GREATEST(0, LEAST(100, v_score::INTEGER)),
    'components', jsonb_build_array('freshness','conflicts')
  );
END;

$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.update_email_template(p_business_id UUID,
  p_template_type TEXT,
  p_subject TEXT,
  p_heading TEXT,
  p_body TEXT,
  p_cta_text TEXT,
  p_cta_url TEXT)
RETURNS email_templates
AS $guard$

DECLARE
  v_template email_templates;
BEGIN
-- Canonical tenant guard: only members of the business may use this RPC (Session-33 security closure).
  IF NOT EXISTS (SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id = p_business_id) THEN
    RETURN NULL;
  END IF;

  UPDATE email_templates
  SET 
    subject = COALESCE(p_subject, subject),
    heading = COALESCE(p_heading, heading),
    body = COALESCE(p_body, body),
    cta_text = COALESCE(p_cta_text, cta_text),
    cta_url = COALESCE(p_cta_url, cta_url),
    updated_at = now()
  WHERE business_id = p_business_id AND template_type = p_template_type
  RETURNING * INTO v_template;
  
  IF v_template IS NULL THEN
    INSERT INTO email_templates (business_id, template_type, subject, heading, body, cta_text, cta_url)
    VALUES (p_business_id, p_template_type, p_subject, p_heading, p_body, p_cta_text, p_cta_url)
    RETURNING * INTO v_template;
  END IF;
  
  RETURN v_template;
END;

$guard$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.update_subscription_from_webhook(p_business_id UUID,
  p_provider TEXT,
  p_provider_subscription_id TEXT,
  p_status TEXT,
